// const TOBREAK: BreakHandler[] = []

export class Move implements PathData {
  hash: string

  targetPos: Vec3

  public readonly cachedVec: Vec3
  // remainingBlocks: number = 0 // TODO: implement this

  toPlace: PlaceHandler[]
  toBreak: BreakHandler[]
  optimizedExecutor?: MovementExecutor

  metadata?: Record<string, any>

  constructor (
    public readonly x: number,
    public readonly y: number,
    public readonly z: number,
    toPlace: PlaceHandler[],
    toBreak: BreakHandler[],
    public readonly remainingBlocks: number,
    public readonly cost: number,
    public readonly moveType: MovementProvider,
    public readonly entryPos: Vec3,
    public readonly entryVel: Vec3,
    public readonly exitPos: Vec3,
    public readonly exitVel: Vec3,
    // public readonly interactMap: Map<string, PlaceHandler | BreakHandler>,
    public readonly parent?: Move
  ) {
    this.x = Math.floor(x)
    this.y = Math.floor(y)
    this.z = Math.floor(z)
    this.hash = `${this.x},${this.y},${this.z}` // this.x + ',' + this.y + ',' + this.z
    this.targetPos = this.exitPos

    this.cachedVec = new Vec3(this.x, this.y, this.z)
    Object.freeze(this.cachedVec)

    // this.toPlace = TOPLACE
    // this.toBreak = TOBREAK
    this.toPlace = toPlace
    this.toBreak = toBreak
    // this.x = x;
    // this.y = y;
    // this.z = z;
    // this.hash = this.x.toFixed(1) + "," + this.y.toFixed(1) + "," + this.z.toFixed(1);
  }

  static startMove (type: MovementProvider, pos: Vec3, vel: Vec3, remainingBlocks: number): Move {
    return new Move(pos.x, pos.y, pos.z, [], [], remainingBlocks, 0, type, pos, vel, pos, vel)
    // new Map());
  }

  static fromPreviousState (
    cost: number,
    state: EntityState,
    prevMove: Move,
    type: MovementProvider,
    toPlace: PlaceHandler[] = [],
    toBreak: BreakHandler[] = []
  ): Move {
    // const p = new Map(prevMove.interactMap);
    // for (const breakH of toBreak) {
    //   p.set(`(${breakH.x}, ${breakH.y}, ${breakH.z})`, breakH);
    // }
    // for (const place of toPlace) {
    //   p.set(`(${place.x}, ${place.y}, ${place.z})`, place);
    // }
    return new Move(
      state.pos.x,
      state.pos.y,
      state.pos.z,
      toPlace,
      toBreak,
      prevMove.remainingBlocks - toPlace.length,
      cost,
      type,
      prevMove.exitPos,
      prevMove.exitVel,
      state.pos.clone(),
      state.vel.clone(),
      // prevMove.interactMap,
      prevMove
      // p
    )
  }

  static fromPrevious (
    cost: number,
    pos: Vec3,
    prevMove: Move,
    type: MovementProvider,
    toPlace: PlaceHandler[] = [],
    toBreak: BreakHandler[] = []
  ): Move {
    // const p = new Map(prevMove.interactMap);
    // for (const place of toPlace) {
    //   p.set(`(${place.x}, ${place.y}, ${place.z})`, place);
    // }
    // for (const breakH of toBreak) {
    //   p.set(`(${breakH.x}, ${breakH.y}, ${breakH.z})`, breakH);
    // }
    return new Move(
      pos.x,
      pos.y,
      pos.z,
      toPlace,
      toBreak,
      prevMove.remainingBlocks - toPlace.length,
      cost,
      type,
      prevMove.exitPos,
      prevMove.exitVel,
      pos,
      emptyVec,
      // prevMove.interactMap,
      prevMove
      // p
    )
  }

  public clone (): Move {
    return { ...this } // lazy.
  }

  public get vec (): Vec3 {
    return this.cachedVec
    // return new Vec3(this.x, this.y, this.z)
  }

  public toVecCenter (): Vec3 {
    return new Vec3(this.x + 0.5, this.y, this.z + 0.5)
  }

  public exitRounded (digits: number): Vec3 {
    const mult = Math.pow(10, digits)
    return new Vec3(
      Math.round(this.exitPos.x * mult) / mult,
      Math.round(this.exitPos.y * mult) / mult,
      Math.round(this.exitPos.z * mult) / mult
    )
  }

  toString (): String {
    // eslint-disable-next-line @typescript-eslint/restrict-template-expressions
    return `Move { ${this.moveType.constructor.name} | ${this.x}, ${this.y}, ${this.z} | ${this.entryPos} | ${this.exitPos} }`
  }
}

import { AABB } from '@nxg-org/mineflayer-util-plugin'
import { ControlStateHandler } from '@nxg-org/mineflayer-physics-util'
import { Vec3 } from 'vec3'
import * as goals from '../../goals'
import { Move } from '../../move'
import { CancelError } from '../../exceptions'
import { botSmartMovement, botStrafeMovement } from '../../movements/controls'
import { CompleteOpts, MovementExecutor } from '../../movements/movementExecutor'
import { ParkourJumpHelper, getUnderlyingBBs } from '../../movements/movementUtils'
import { World } from '../../world/worldInterface'
import { MovementOptions } from '../../movements'

export interface AroundCornerExecutorSettings {
  aroundCornerWaitForVelocitySettle?: boolean
}

/**
 * Around-the-corner diagonal executor.
 *
 * This is intentionally parkour-like rather than ladder-like:
 * - it uses a normal jump state machine
 * - it aims at the landing block, not a ladder-backed fallback
 * - ladder metadata is only used to refine the aim when the provider found one
 */
export class AroundCornerDiagonalExecutor extends MovementExecutor {
  private readonly jumpHelper: ParkourJumpHelper = new ParkourJumpHelper(this.bot, this.world)

  private executing = false
  private hasLeftGround = false
  private lockedYaw: number | null = null
  private backingUp = false
  private backupSettling = false
  private backupAttempted = false
  private backupTarget: Vec3 | null = null
  private _lookAtInFlight: Promise<void> | null = null
  private _pendingLookTarget: Vec3 | null = null

  protected static readonly APPROACH_YAW_EPS: number = 0.12
  private readonly waitForVelocitySettle: boolean

  constructor(
    bot: import('mineflayer').Bot,
    world: World,
    settings: Partial<MovementOptions> & AroundCornerExecutorSettings = {}
  ) {
    super(bot, world, settings)
    this.waitForVelocitySettle = settings.aroundCornerWaitForVelocitySettle ?? false
  }

  protected isComplete(startMove: Move, endMove?: Move, opts: CompleteOpts = {}): boolean {
    return super.isComplete(startMove, endMove, opts)
  }

  override reset(): void {
    this.executing = false
    this.hasLeftGround = false
    this.lockedYaw = null
    this.backingUp = false
    this.backupSettling = false
    this.backupAttempted = false
    this.backupTarget = null
    this._lookAtInFlight = null
    this._pendingLookTarget = null
    super.reset()
  }

  protected _debugLog(..._args: unknown[]): void {
    // Kept quiet for now.
  }

  protected _lockCurrentYaw(targetYaw: number): void {
    this.lockedYaw = targetYaw
  }

  protected _clearLockedYaw(): void {
    this.lockedYaw = null
  }

  protected _applyLockedYaw(): void {
    if (this.lockedYaw != null) {
      this.bot.entity.yaw = this.lockedYaw
    }
  }

  protected _getTargetBlock(thisMove: Move): Vec3 {
    return thisMove.exitPos.offset(0, -1, 0)
  }

  protected _getLadderSupport(thisMove: Move): Vec3 | null {
    const support = thisMove.metadata?.ladderSupport
    if (support == null) return null
    if (support instanceof Vec3) return support
    if (
      typeof support.x === 'number' &&
      typeof support.y === 'number' &&
      typeof support.z === 'number'
    ) {
      return new Vec3(support.x, support.y, support.z)
    }
    return null
  }

  protected _getTargetEyeVec(thisMove: Move): Vec3 {
    const target = this._getTargetBlock(thisMove)
    const ladderSupport = this._getLadderSupport(thisMove)

    if (ladderSupport != null) {
      const ladderInfo = this.getBlockInfoRaw(ladderSupport)
      const ladderFace = this._getTouchingLadderFace(ladderInfo.getBBs(), AABB.fromBlockPos(target))
      if (ladderFace != null) return ladderFace
    }

    return this.jumpHelper.findGoalVertex(AABB.fromBlockPos(target))
  }

  protected _getTouchingLadderFace(ladderBBs: AABB[], supportBB: AABB): Vec3 | null {
    for (const ladderBB of ladderBBs) {
      if (!ladderBB.collides(supportBB)) continue

      const contact = ladderBB.intersect(supportBB)
      return contact.getCenter()
    }

    return null
  }

  protected _getUnderlyingBbs(thisMove: Move): AABB[] {
    const bbs = getUnderlyingBBs(this.world, this.bot.entity.position, 0.6)
    if (bbs.length === 0) {
      bbs.push(AABB.fromBlockPos(thisMove.entryPos.offset(0, -1, 0)))
    }
    return bbs
  }

  protected _desiredYawTo(target: Vec3): number {
    const dx = target.x - this.bot.entity.position.x
    const dz = target.z - this.bot.entity.position.z
    return Math.atan2(-dx, -dz)
  }

  protected _yawDeltaAbs(targetYaw: number): number {
    let delta = targetYaw - this.bot.entity.yaw
    while (delta > Math.PI) delta -= Math.PI * 2
    while (delta < -Math.PI) delta += Math.PI * 2
    return Math.abs(delta)
  }

  protected _isYawAlignedForApproach(target: Vec3): boolean {
    return (
      this._yawDeltaAbs(this._desiredYawTo(target)) <= AroundCornerDiagonalExecutor.APPROACH_YAW_EPS
    )
  }

  protected _queueLookAtSync(target: Vec3): Promise<void> {
    this._pendingLookTarget = target.offset(0, this.bot.entity.position.y - target.y, 0)

    if (this._lookAtInFlight != null) return this._lookAtInFlight

    this._lookAtInFlight = (async () => {
      try {
        while (this._pendingLookTarget != null) {
          const nextTarget = this._pendingLookTarget
          this._pendingLookTarget = null
          await this.lookAt(nextTarget, true)
        }
      } finally {
        this._lookAtInFlight = null
      }
    })()

    return this._lookAtInFlight
  }

  protected _clearBackupState(): void {
    this.backingUp = false
    this.backupSettling = false
    this.backupTarget = null
  }

  protected _getBackupTarget(thisMove: Move): Vec3 | null {
    const targetEyeVec = this._getTargetEyeVec(thisMove)
    const pos = thisMove.entryPos
    return this.jumpHelper.findViableBackupVertex(this._getTargetBlock(thisMove), targetEyeVec, pos)
  }

  protected _shouldSneakDuringBackup(thisMove: Move, target: Vec3): boolean {
    if (this.bot.entity.position.xzDistanceTo(target) < 0.1) return true

    const controls = ControlStateHandler.COPY_BOT(this.bot).set('sneak', false).set('jump', false)
    const ectx = this.simForward({ ticks: 2, controls })
    return ectx.state.pos.y < this.bot.entity.position.y && !ectx.state.onGround
  }

  protected _applyBackupControls(thisMove: Move, target: Vec3): void {
    this._lockCurrentYaw(this._desiredYawTo(target))
    void this._queueLookAtSync(target)
    this.bot.clearControlStates()
    botSmartMovement(this.bot, target, this.settings.allowSprinting)
    botStrafeMovement(this.bot, target, true)
    this.bot.setControlState('sneak', this._shouldSneakDuringBackup(thisMove, target))
  }

  protected _startBackup(thisMove: Move): boolean {
    this.backupTarget ??= this._getBackupTarget(thisMove)
    if (this.backupTarget == null) return false

    this.backingUp = true
    this.backupAttempted = true
    this._applyBackupControls(thisMove, this.backupTarget)
    return true
  }

  protected _advanceBackup(thisMove: Move): 'backing' | 'recheck' | 'jump' | 'failed' {
    this.backupTarget ??= this._getBackupTarget(thisMove)
    if (this.backupTarget == null) return 'failed'

    const jumpState = this._getJumpState(thisMove)
    if (jumpState.canJumpFromEdge) {
      this._clearBackupState()
      this._clearLockedYaw()
      this.bot.clearControlStates()
      return 'jump'
    }

    const dist = this.bot.entity.position.xzDistanceTo(this.backupTarget)
    const xzVel = this.bot.entity.velocity.offset(0, -this.bot.entity.velocity.y, 0)

    if (dist > 0.08) {
      this.backupSettling = false
      this._applyBackupControls(thisMove, this.backupTarget)
      return 'backing'
    }

    this.backupSettling = true
    this.bot.clearControlStates()
    this.bot.setControlState('sneak', this._shouldSneakDuringBackup(thisMove, this.backupTarget))

    if (this.waitForVelocitySettle && xzVel.norm() > 0.05) {
      return 'backing'
    }

    this._clearBackupState()
    this._clearLockedYaw()
    this.bot.clearControlStates()
    return 'recheck'
  }

  protected _getJumpState(thisMove: Move): {
    target: Vec3
    targetEyeVec: Vec3
    canDirectJump: boolean
    canJumpFromEdge: boolean
    fallOffEdge: boolean
  } {
    const target = this._getTargetBlock(thisMove)
    const targetEyeVec = this._getTargetEyeVec(thisMove)
    const bbs = this._getUnderlyingBbs(thisMove)

    return {
      target,
      targetEyeVec,
      canDirectJump: this.jumpHelper.simForwardMove(target, targetEyeVec),
      canJumpFromEdge: this.jumpHelper.simJumpFromEdge(bbs, target),
      fallOffEdge:
        thisMove.entryPos.y > thisMove.exitPos.y && this.jumpHelper.simFallOffEdge(target)
    }
  }

  protected _clearApproachControls(): void {
    this.bot.setControlState('forward', false)
    this.bot.setControlState('back', false)
    this.bot.setControlState('left', false)
    this.bot.setControlState('right', false)
    this.bot.setControlState('jump', false)
    this.bot.setControlState('sprint', false)
    this.bot.setControlState('sneak', false)
  }

  protected _applyExecutionControls(thisMove: Move, _target: Vec3): void {
    this._applyLockedYaw()
    this.bot.clearControlStates()

    const ectx = this.simForward({ ticks: 1 })
    if (!this.bot.entity.onGround && this.bot.entity.position.y > thisMove.entryPos.y + 0.05)
      this.hasLeftGround = true
    const launchJump = !this.hasLeftGround && thisMove.exitPos.y >= thisMove.entryPos.y
    const ladderCollideJump = ectx.state.isCollidedHorizontally
    const jump =
      launchJump ||
      ladderCollideJump ||
      (ectx.position.y < this.bot.entity.position.y && !ectx.state.onGround)

    this.bot.setControlState('forward', true)
    this.bot.setControlState('sprint', this.settings.allowSprinting)
    this.bot.setControlState('back', false)
    this.bot.setControlState('jump', jump)
    this.bot.setControlState('sneak', false)
  }

  protected _startExecution(target: Vec3, thisMove: Move): void {
    this.executing = true
    this.hasLeftGround = false
    this._lockCurrentYaw(this._desiredYawTo(target))
    this._applyExecutionControls(thisMove, target)
  }

  override async align(thisMove: Move, _tickCount: number, _goal: goals.Goal): Promise<boolean> {
    this.executing = false
    this.hasLeftGround = false
    this._clearLockedYaw()

    while (true) {
      if (this.tooLowCheck(thisMove)) {
        const botY = this.getTooLowCheckY()
        throw new CancelError(
          `y level: too low! ${botY}, ${thisMove.entryPos.y} ${thisMove.exitPos.y}`
        )
      }

      if (this.backingUp) {
        const backupState = this._advanceBackup(thisMove)
        if (backupState === 'backing') return false
        if (backupState === 'jump') continue
      }

      const jumpState = this._getJumpState(thisMove)
      const { targetEyeVec, canDirectJump, canJumpFromEdge, fallOffEdge } = jumpState

      void this._queueLookAtSync(targetEyeVec)

      if (canDirectJump || fallOffEdge) {
        if (!this._isYawAlignedForApproach(targetEyeVec)) {
          this._clearApproachControls()
          return false
        }

        this._clearBackupState()
        this._startExecution(targetEyeVec, thisMove)
        return true
      }

      if (canJumpFromEdge) {
        if (!this._isYawAlignedForApproach(targetEyeVec)) {
          this._clearApproachControls()
          return false
        }

        this._clearBackupState()
        this._startExecution(targetEyeVec, thisMove)
        return true
      }

      if (this.backupAttempted) {
        this._clearBackupState()
        throw new CancelError('AroundCorner: no feasible jump after backing up')
      }

      if (this.bot.entity.onGround) {
        this.bot.clearControlStates()
      }

      if (this._startBackup(thisMove)) return false

      this.bot.clearControlStates()
      throw new CancelError('AroundCorner: no feasible jump')
    }
  }

  override async performInit(thisMove: Move, _currentIndex: number, _path: Move[]): Promise<void> {
    this._clearLockedYaw()
    this._clearBackupState()
    this.backupAttempted = false
  }

  override performPerTick(
    thisMove: Move,
    _tickCount: number,
    _currentIndex: number,
    _path: Move[]
  ): boolean | Promise<boolean> {
    if (this.tooLowCheck(thisMove)) throw new CancelError('AroundCorner: missed the landing')
    const target = this._getTargetBlock(thisMove)
    const targetEyeVec = this._getTargetEyeVec(thisMove)

    if (this.backingUp) {
      const backupState = this._advanceBackup(thisMove)
      if (backupState === 'backing') return false
      if (backupState === 'jump') {
        this._startExecution(targetEyeVec, thisMove)
        return false
      }

      this._startExecution(targetEyeVec, thisMove)
      return false
    }

    if (this.executing) {
      this._lockCurrentYaw(this._desiredYawTo(targetEyeVec))
      this._applyExecutionControls(thisMove, targetEyeVec)
      return this.isComplete(thisMove)
    }

    const jumpState = this._getJumpState(thisMove)
    const { canDirectJump, canJumpFromEdge, fallOffEdge } = jumpState

    void this._queueLookAtSync(targetEyeVec)

    if (canDirectJump || fallOffEdge || canJumpFromEdge) {
      if (!this._isYawAlignedForApproach(targetEyeVec)) {
        this._clearApproachControls()
        return false
      }

      this._clearBackupState()
      this._startExecution(targetEyeVec, thisMove)
      return false
    }

    if (this.backupAttempted) {
      this._clearBackupState()
      throw new CancelError('AroundCorner: no feasible jump after backing up')
    }

    if (this._startBackup(thisMove)) return false

    this.bot.clearControlStates()
    throw new CancelError('AroundCorner: no feasible jump')
  }
}

// Adapted from Rewrite examples/ladders (MIT).
import { JUMP_ONE_BLOCK_COST, COST_INF } from '../costs'
import { Vec3 } from 'vec3'
import * as goals from '../../goals'
import { Move } from '../../move'
import { Movement } from '../movement'
import { MovementProvider } from '../movementProvider'
import { BlockInfo } from '../../world/cacheWorld'

const DIAGONAL_COST = Math.SQRT2

function closedKey(pos: Vec3): string {
  return `${pos.x},${pos.y},${pos.z}`
}

function pushMove(
  neighbors: Move[],
  node: Move,
  cost: number,
  landing: Vec3,
  moveType: MovementProvider
): void {
  cost += moveType.exclusionStep(moveType.getBlockInfoRaw(landing))
  if (cost >= COST_INF) return
  neighbors.push(Move.fromPrevious(cost, landing.offset(0.5, 0, 0.5), node, moveType))
}

/**
 * Around-the-corner diagonal movement.
 *
 * This keeps the same diagonal search shape as the ladder diagonal provider,
 * but adds the corner wall checks needed for the turn.
 */
export class AroundCornerDiagonal extends MovementProvider {
  movementDirs = Movement.diagonalDirs

  static allowOffsetDiagonals = true

  provideMovements(start: Move, storage: Move[], goal: goals.Goal, closed: Set<string>): void {
    for (const dir of Movement.diagonalDirs) {
      this.getMoveAroundCornerDiagonal(start, dir, storage, closed)
    }
  }

  /**
   * One-block-down around-the-corner jump.
   */
  private canCornerDropLanding(
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontD: BlockInfo,
    blockEPhysical: boolean
  ): boolean {
    return (
      blockEPhysical &&
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.walkthrough &&
      blockFrontD.physical &&
      ceilingClear
    )
  }

  /**
   * Flat around-the-corner jump.
   */
  private canCornerFlatLanding(
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontC: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.physical &&
      blockFrontC.physical &&
      ceilingClear
    )
  }

  /**
   * Two-block-up around-the-corner jump.
   */
  private canCornerTwoUpLanding(
    ceilingClear: boolean,
    blockA: BlockInfo,
    blockB: BlockInfo
  ): boolean {
    return blockA.walkthrough && blockB.physical && ceilingClear
  }

  /**
   * One-block-up around-the-corner jump.
   */
  private canCornerOneUpLanding(
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontB: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.physical &&
      blockD.walkthrough &&
      blockFrontB.physical &&
      ceilingClear
    )
  }

  private getMoveAroundCornerDiagonal(
    node: Move,
    dir: Vec3,
    neighbors: Move[],
    closed: Set<string>
  ): void {
    const block0 = this.getBlockInfo(node, 0, -1, 0)
    if (!block0.physical) return

    const block00 = this.getBlockInfo(node, 0, 0, 0)
    if (block00.liquid) return

    const block1Floor = this.getBlockInfo(node, dir.x, -1, dir.z)
    if (block1Floor.physical && block1Floor.height >= block0.height) return

    if (!this.getBlockInfo(node, dir.x, 0, dir.z).physical) return
    if (!this.getBlockInfo(node, dir.x, 1, dir.z).physical) return
    if (!this.getBlockInfo(node, dir.x, 0, 0).physical) return
    if (!this.getBlockInfo(node, 0, 0, dir.z).physical) return
    if (!this.getBlockInfo(node, dir.x, 1, 0).physical) return
    if (!this.getBlockInfo(node, 0, 1, dir.z).physical) return

    const cost0 = JUMP_ONE_BLOCK_COST + this.settings.jumpCost
    const maxD = this.settings.allowSprinting ? 6 : 4

    for (let d = 2; d <= maxD; d++) {
      if (this.tryLanding(node, dir, d, d, cost0, block0, neighbors, closed)) break
    }

    if (AroundCornerDiagonal.allowOffsetDiagonals) {
      for (let major = 2; major <= maxD; major++) {
        for (let minor = 1; minor < major; minor++) {
          if (minor === major) continue

          if (this.tryLanding(node, dir, minor, major, cost0, block0, neighbors, closed)) return
          if (this.tryLanding(node, dir, major, minor, cost0, block0, neighbors, closed)) return
        }
      }
    }
  }

  private tryLanding(
    node: Move,
    dir: Vec3,
    xSteps: number,
    zSteps: number,
    cost0: number,
    block0: BlockInfo,
    neighbors: Move[],
    closed: Set<string>
  ): boolean {
    const dx = dir.x * xSteps
    const dz = dir.z * zSteps

    const travel = Math.sqrt(xSteps * xSteps + zSteps * zSteps)
    const cost = cost0 + this.travelCost(travel)
    const majorIsX = xSteps > zSteps
    const majorIsZ = zSteps > xSteps
    const frontDx = dx - (majorIsX || xSteps === zSteps ? dir.x : 0)
    const frontDz = dz - (majorIsZ || xSteps === zSteps ? dir.z : 0)

    const flag0 = !closed.has(closedKey(new Vec3(node.x + dx, node.y - 1, node.z + dz)))
    const flag1 = !closed.has(closedKey(new Vec3(node.x + dx, node.y, node.z + dz)))
    const flag2 = !closed.has(closedKey(new Vec3(node.x + dx, node.y + 1, node.z + dz)))

    if (!flag0 && !flag1 && !flag2) return false

    const blockD = this.getBlockInfo(node, dx, -1, dz)
    if (blockD.climbable) return false

    const blockA = this.getBlockInfo(node, dx, 2, dz)
    const blockB = this.getBlockInfo(node, dx, 1, dz)
    const blockC = this.getBlockInfo(node, dx, 0, dz)
    const blockFrontD = this.getBlockInfo(node, frontDx, -1, frontDz)
    const blockFrontC = this.getBlockInfo(node, frontDx, 0, frontDz)
    const blockFrontB = this.getBlockInfo(node, frontDx, 1, frontDz)

    if (!this.getBlockInfo(node, dx, 0, 0).physical) return false
    if (!this.getBlockInfo(node, 0, 0, dz).physical) return false
    if (!this.getBlockInfo(node, dx, 1, 0).physical) return false
    if (!this.getBlockInfo(node, 0, 1, dz).physical) return false

    const blockE = this.getBlockInfo(node, dx, -2, dz)

    const ceilingClear =
      this.getBlockInfo(node, 0, 2, 0).walkthrough &&
      this.getBlockInfo(node, dx, 2, dz).walkthrough &&
      this.getBlockInfo(node, dx, 2, 0).walkthrough &&
      this.getBlockInfo(node, 0, 2, dz).walkthrough

    if (
      flag0 &&
      this.canCornerDropLanding(ceilingClear, blockB, blockC, blockD, blockFrontD, blockE.physical)
    ) {
      pushMove(neighbors, node, cost, blockD.position, this)
      return true
    }

    if (flag1 && this.canCornerFlatLanding(ceilingClear, blockB, blockC, blockD, blockFrontC)) {
      pushMove(neighbors, node, cost + 3, blockC.position, this)
      return true
    }

    if (flag2 && this.canCornerTwoUpLanding(ceilingClear, blockA, blockB)) {
      pushMove(neighbors, node, cost, blockA.position, this)
      return true
    }

    if (flag2 && this.canCornerOneUpLanding(ceilingClear, blockB, blockC, blockD, blockFrontB)) {
      if (blockC.height - block0.height > 1.2) return false
      if (travel > 3.0) return false
      pushMove(neighbors, node, cost, blockB.position, this)
      return true
    }

    return false
  }
}

import { AABB, AABBUtils } from '@nxg-org/mineflayer-util-plugin'
import { ControlStateHandler } from '@nxg-org/mineflayer-physics-util'
import { Vec3 } from 'vec3'
import * as goals from '../../goals'
import { Move } from '../../move'
import { CancelError } from '../../exceptions'
import { botSmartMovement, botStrafeMovement } from '../../movements/controls'
import { CompleteOpts, MovementExecutor } from '../../movements/movementExecutor'
import { ParkourJumpHelper, getUnderlyingBBs } from '../../movements/movementUtils'
import { World } from '../../world/worldInterface'
import { MovementOptions } from '../../movements'
const { PlayerState } = require('prismarine-physics')

export interface LadderExecutorSettings {
  ladderWaitForVelocitySettle?: boolean
}

/**
 * Ladder executor.
 *
 * This keeps the same overall shape as the parkour executor, but it is more
 * forgiving: jump simulation only advises the decision, while the actual
 * control loop is handled directly here.
 */
export class LadderForwardExecutor extends MovementExecutor {
  private readonly jumpHelper: ParkourJumpHelper = new ParkourJumpHelper(this.bot, this.world)

  private executing = false
  private hasLeftGround = false
  private lockedYaw: number | null = null
  private backingUp = false
  private backupSettling = false
  private backupAttempted = false
  private backupTarget: Vec3 | null = null
  private _lookAtInFlight: Promise<void> | null = null
  private _pendingLookTarget: Vec3 | null = null

  protected static readonly APPROACH_YAW_EPS: number = 0.16
  private readonly waitForVelocitySettle: boolean

  constructor(
    bot: import('mineflayer').Bot,
    world: World,
    settings: Partial<MovementOptions> & LadderExecutorSettings = {}
  ) {
    super(bot, world, settings)
    this.waitForVelocitySettle = settings.ladderWaitForVelocitySettle ?? false
  }

  protected isComplete(startMove: Move, endMove?: Move, opts: CompleteOpts = {}): boolean {
    return super.isComplete(startMove, endMove, opts)
  }

  override reset(): void {
    this.executing = false
    this.hasLeftGround = false
    this.lockedYaw = null
    this.backingUp = false
    this.backupSettling = false
    this.backupAttempted = false
    this.backupTarget = null
    this._lookAtInFlight = null
    this._pendingLookTarget = null
    super.reset()
  }

  protected _debugLog(..._args: unknown[]): void {
    // Intentionally quiet for now.
  }

  protected _lockCurrentYaw(targetYaw: number): void {
    this.lockedYaw = targetYaw
  }

  protected _clearLockedYaw(): void {
    this.lockedYaw = null
  }

  protected _applyLockedYaw(): void {
    if (this.lockedYaw != null) {
      this.bot.entity.yaw = this.lockedYaw
    }
  }

  protected _getTargetBlock(thisMove: Move): Vec3 {
    return thisMove.exitPos.offset(0, -1, 0)
  }

  protected _getLadderSupport(thisMove: Move): Vec3 | null {
    const support = thisMove.metadata?.ladderSupport
    if (support == null) return null
    if (support instanceof Vec3) return support
    if (
      typeof support.x === 'number' &&
      typeof support.y === 'number' &&
      typeof support.z === 'number'
    ) {
      return new Vec3(support.x, support.y, support.z)
    }
    return null
  }

  protected _getTargetEyeVec(thisMove: Move): Vec3 {
    // Aim through the ladder onto the landing, so reaching its face does not
    // leave the bot oscillating on the block boundary.
    return thisMove.exitPos.clone()
  }

  protected _getTouchingLadderFace(ladderBBs: AABB[], supportBB: AABB): Vec3 | null {
    for (const ladderBB of ladderBBs) {
      if (!ladderBB.collides(supportBB)) continue

      const contact = ladderBB.intersect(supportBB)
      return contact.getCenter()
    }

    return null
  }

  protected _getUnderlyingBbs(thisMove: Move): AABB[] {
    const bbs = getUnderlyingBBs(this.world, this.bot.entity.position, 0.6)
    if (bbs.length === 0) {
      bbs.push(AABB.fromBlockPos(thisMove.entryPos.offset(0, -1, 0)))
    }
    return bbs
  }

  protected _desiredYawTo(target: Vec3): number {
    const dx = target.x - this.bot.entity.position.x
    const dz = target.z - this.bot.entity.position.z
    return Math.atan2(-dx, -dz)
  }

  protected _yawDeltaAbs(targetYaw: number): number {
    let delta = targetYaw - this.bot.entity.yaw
    while (delta > Math.PI) delta -= Math.PI * 2
    while (delta < -Math.PI) delta += Math.PI * 2
    return Math.abs(delta)
  }

  protected _isYawAlignedForApproach(target: Vec3): boolean {
    return this._yawDeltaAbs(this._desiredYawTo(target)) <= LadderForwardExecutor.APPROACH_YAW_EPS
  }

  protected _queueLookAtSync(target: Vec3): Promise<void> {
    this._pendingLookTarget = target.offset(0, this.bot.entity.position.y - target.y, 0)

    if (this._lookAtInFlight != null) return this._lookAtInFlight

    this._lookAtInFlight = (async () => {
      try {
        while (this._pendingLookTarget != null) {
          const nextTarget = this._pendingLookTarget
          this._pendingLookTarget = null
          await this.lookAt(nextTarget, true)
        }
      } finally {
        this._lookAtInFlight = null
      }
    })()

    return this._lookAtInFlight
  }

  protected _clearBackupState(): void {
    this.backingUp = false
    this.backupSettling = false
    this.backupTarget = null
  }

  protected _getBackupTarget(thisMove: Move): Vec3 | null {
    const targetEyeVec = this._getTargetEyeVec(thisMove)
    const pos = thisMove.entryPos
    return this.jumpHelper.findViableBackupVertex(this._getTargetBlock(thisMove), targetEyeVec, pos)
  }

  protected _shouldSneakDuringBackup(thisMove: Move, target: Vec3): boolean {
    if (this.bot.entity.position.xzDistanceTo(target) < 0.1) return true

    const controls = ControlStateHandler.COPY_BOT(this.bot).set('sneak', false).set('jump', false)
    const ectx = this.simForward({ ticks: 2, controls })
    return ectx.state.pos.y < this.bot.entity.position.y && !ectx.state.onGround
  }

  protected _applyBackupControls(thisMove: Move, target: Vec3): void {
    this._lockCurrentYaw(this._desiredYawTo(target))
    void this._queueLookAtSync(target)
    this.bot.clearControlStates()
    botSmartMovement(this.bot, target, this.settings.allowSprinting)
    botStrafeMovement(this.bot, target, true)
    this.bot.setControlState('sneak', this._shouldSneakDuringBackup(thisMove, target))
  }

  protected _startBackup(thisMove: Move): boolean {
    this.backupTarget ??= this._getBackupTarget(thisMove)
    if (this.backupTarget == null) return false

    this.backingUp = true
    this.backupAttempted = true
    this._applyBackupControls(thisMove, this.backupTarget)
    return true
  }

  protected _advanceBackup(thisMove: Move): 'backing' | 'recheck' | 'jump' | 'failed' {
    this.backupTarget ??= this._getBackupTarget(thisMove)
    if (this.backupTarget == null) return 'failed'

    const jumpState = this._getJumpState(thisMove)
    if (jumpState.canJumpFromEdge) {
      this._clearBackupState()
      this._clearLockedYaw()
      this.bot.clearControlStates()
      return 'jump'
    }

    const dist = this.bot.entity.position.xzDistanceTo(this.backupTarget)
    const xzVel = this.bot.entity.velocity.offset(0, -this.bot.entity.velocity.y, 0)

    if (dist > 0.08) {
      this.backupSettling = false
      this._applyBackupControls(thisMove, this.backupTarget)
      return 'backing'
    }

    this.backupSettling = true
    this.bot.clearControlStates()
    this.bot.setControlState('sneak', this._shouldSneakDuringBackup(thisMove, this.backupTarget))

    if (this.waitForVelocitySettle && xzVel.norm() > 0.05) {
      return 'backing'
    }

    this._clearBackupState()
    this._clearLockedYaw()
    this.bot.clearControlStates()
    return 'recheck'
  }

  protected _getJumpState(thisMove: Move): {
    target: Vec3
    targetEyeVec: Vec3
    canDirectJump: boolean
    canJumpFromEdge: boolean
    fallOffEdge: boolean
  } {
    const target = this._getTargetBlock(thisMove)
    const targetEyeVec = thisMove.exitPos.clone()
    const canReach = (fromEdge: boolean): boolean => {
      const control = {
        forward: true,
        back: false,
        left: false,
        right: false,
        sneak: false,
        sprint: this.settings.allowSprinting,
        jump: !fromEdge
      }
      const state = new PlayerState(this.bot, control)
      const world = { getBlock: (position: Vec3) => this.world.getBlock(position) }
      let launched = !fromEdge
      for (let tick = 0; tick < 50; tick++) {
        state.yaw = Math.atan2(-(targetEyeVec.x - state.pos.x), -(targetEyeVec.z - state.pos.z))
        if (!launched) {
          const probe = Object.assign(Object.create(Object.getPrototypeOf(state)), state, {
            pos: state.pos.clone(),
            vel: state.vel.clone()
          })
          ;(this.bot.physics as any).simulatePlayer(probe, world)
          if (!probe.onGround || probe.isCollidedHorizontally) launched = true
        }
        state.control.jump = launched
        ;(this.bot.physics as any).simulatePlayer(state, world)
        if (state.pos.y < Math.min(thisMove.entryPos.y, thisMove.exitPos.y) - 0.5 || state.isInLava)
          return false
        if (
          state.pos.y >= thisMove.exitPos.y - 0.05 &&
          state.pos.xzDistanceTo(thisMove.exitPos) < 0.65
        )
          return true
      }
      return false
    }

    return {
      target,
      targetEyeVec,
      canDirectJump: canReach(false),
      canJumpFromEdge: canReach(true),
      fallOffEdge:
        thisMove.entryPos.y > thisMove.exitPos.y && this.jumpHelper.simFallOffEdge(target)
    }
  }

  protected _clearApproachControls(): void {
    this.bot.setControlState('forward', false)
    this.bot.setControlState('back', false)
    this.bot.setControlState('left', false)
    this.bot.setControlState('right', false)
    this.bot.setControlState('jump', false)
    this.bot.setControlState('sprint', false)
    this.bot.setControlState('sneak', false)
  }

  protected _applyApproachControls(_thisMove: Move, target: Vec3): void {
    this._applyLockedYaw()
    this.bot.clearControlStates()
    botSmartMovement(this.bot, target, this.settings.allowSprinting)
    botStrafeMovement(this.bot, target, true)
    this.bot.setControlState('jump', false)
    this.bot.setControlState('sneak', false)
  }

  protected _applyExecutionControls(thisMove: Move, _target: Vec3): void {
    this._applyLockedYaw()
    this.bot.clearControlStates()

    if (!this.bot.entity.onGround && this.bot.entity.position.y > thisMove.entryPos.y + 0.05)
      this.hasLeftGround = true
    const launchJump = !this.hasLeftGround && thisMove.exitPos.y >= thisMove.entryPos.y
    const jump =
      this.bot.entity.position.y < thisMove.exitPos.y - 0.05 ||
      (launchJump && this.bot.entity.position.y <= thisMove.entryPos.y + 0.1)
    this.bot.setControlState('forward', true)
    this.bot.setControlState('sprint', this.settings.allowSprinting)
    this.bot.setControlState('back', false)
    this.bot.setControlState('jump', jump)
    this.bot.setControlState('sneak', false)
  }

  protected _startExecution(target: Vec3, thisMove: Move): void {
    this.executing = true
    this.hasLeftGround = false
    this._lockCurrentYaw(this._desiredYawTo(target))
    this._applyExecutionControls(thisMove, target)
  }

  override async align(thisMove: Move, _tickCount: number, _goal: goals.Goal): Promise<boolean> {
    this.executing = false
    this.hasLeftGround = false
    this._clearLockedYaw()

    while (true) {
      if (this.tooLowCheck(thisMove)) {
        const botY = this.getTooLowCheckY()
        throw new CancelError(
          `y level: too low! ${botY}, ${thisMove.entryPos.y} ${thisMove.exitPos.y}`
        )
      }

      if (this.backingUp) {
        const backupState = this._advanceBackup(thisMove)
        if (backupState === 'backing') return false
        if (backupState === 'jump') continue
      }

      const jumpState = this._getJumpState(thisMove)
      const { targetEyeVec, canDirectJump, canJumpFromEdge, fallOffEdge } = jumpState

      void this._queueLookAtSync(targetEyeVec)

      if (canDirectJump || fallOffEdge) {
        if (!this._isYawAlignedForApproach(targetEyeVec)) {
          this._clearApproachControls()
          return false
        }

        this._clearBackupState()
        this._startExecution(targetEyeVec, thisMove)
        return true
      }

      if (canJumpFromEdge) {
        this._clearBackupState()
        this._clearLockedYaw()

        if (!this._isYawAlignedForApproach(targetEyeVec)) {
          this._clearApproachControls()
          return false
        }

        this._applyApproachControls(thisMove, targetEyeVec)
        return false
      }

      if (this.backupAttempted) {
        this._clearBackupState()
        this._clearLockedYaw()
        this.bot.clearControlStates()
        throw new CancelError('LadderExecutor: will not make this jump after backing up!')
      }

      if (this.bot.entity.onGround) {
        this.bot.clearControlStates()
      }

      if (this._startBackup(thisMove)) return false

      this._clearLockedYaw()
      this.bot.clearControlStates()
      throw new CancelError('LadderExecutor: will not make this jump!')
    }
  }

  override async performInit(thisMove: Move, _currentIndex: number, _path: Move[]): Promise<void> {
    this._clearLockedYaw()
    this._clearBackupState()
    this.backupAttempted = false

    // const target = this._getTargetBlock(thisMove)
    // const targetEyeVec = this._getTargetEyeVec(target)
    // void this._queueLookAtSync(targetEyeVec)
  }

  override performPerTick(
    thisMove: Move,
    _tickCount: number,
    _currentIndex: number,
    _path: Move[]
  ): boolean | Promise<boolean> {
    if (this.tooLowCheck(thisMove)) throw new CancelError('Ladder: missed the landing')
    const target = this._getTargetBlock(thisMove)
    const targetEyeVec = this._getTargetEyeVec(thisMove)

    if (this.backingUp) {
      const backupState = this._advanceBackup(thisMove)
      if (backupState === 'backing') return false
      if (backupState === 'jump') {
        this._startExecution(targetEyeVec, thisMove)
        return false
      }

      this._startExecution(targetEyeVec, thisMove)
      return false
    }

    if (this.executing) {
      this._lockCurrentYaw(this._desiredYawTo(targetEyeVec))
      this._applyExecutionControls(thisMove, targetEyeVec)
      return this.isComplete(thisMove)
    }

    const jumpState = this._getJumpState(thisMove)
    const { canDirectJump, canJumpFromEdge, fallOffEdge } = jumpState

    void this._queueLookAtSync(targetEyeVec)

    if (canDirectJump || fallOffEdge) {
      if (!this._isYawAlignedForApproach(targetEyeVec)) {
        this._clearApproachControls()
        return false
      }

      this._clearBackupState()
      this._startExecution(targetEyeVec, thisMove)
      return false
    }

    if (canJumpFromEdge) {
      this._clearBackupState()
      this._clearLockedYaw()

      if (!this._isYawAlignedForApproach(targetEyeVec)) {
        this._clearApproachControls()
        return false
      }

      this._applyApproachControls(thisMove, targetEyeVec)
      return false
    }

    if (this.backupAttempted) {
      this._clearBackupState()
      this._clearLockedYaw()
      this.bot.clearControlStates()
      throw new CancelError('LadderExecutor: will not make this jump after backing up!')
    }

    if (this._startBackup(thisMove)) return false

    this._clearLockedYaw()
    this.bot.clearControlStates()
    throw new CancelError('LadderExecutor: will not make this jump!')
  }
}

/**
 * Ladder diagonal executor.
 *
 * Same control model as the cardinal ladder executor, but with a tighter
 * approach yaw tolerance to match diagonal entries.
 */
export class LadderDiagonalExecutor extends LadderForwardExecutor {
  protected static override readonly APPROACH_YAW_EPS = 0.12

  protected override _isYawAlignedForApproach(target: Vec3): boolean {
    return this._yawDeltaAbs(this._desiredYawTo(target)) <= LadderDiagonalExecutor.APPROACH_YAW_EPS
  }
}

/**
 * Ladder-target executor.
 *
 * This variant treats the ladder block itself as the destination.
 */
export class LadderLandingForwardExecutor extends LadderForwardExecutor {
  protected override _getTargetBlock(thisMove: Move): Vec3 {
    return thisMove.exitPos.offset(0, -1, 0)
  }

  protected override isComplete(startMove: Move, endMove?: Move, opts: CompleteOpts = {}): boolean {
    if (super.isComplete(startMove, endMove, opts)) return true

    const move = endMove ?? startMove
    const ladderPos = this._getLadderSupport(move) ?? move.exitPos.floored()
    const ladderInfo = this.getBlockInfoRaw(ladderPos)
    if (!ladderInfo.climbable) return false

    const playerBB = AABBUtils.getPlayerAABBRaw(this.bot.entity.position, this.bot.entity.height)
    const touchingLadder = ladderInfo.getBBs().some((bb) => bb.collides(playerBB))
    if (!touchingLadder) return false

    return this.bot.entity.position.y >= move.exitPos.y - 0.2
  }
}

/**
 * Ladder-target diagonal executor.
 */
export class LadderLandingDiagonalExecutor extends LadderLandingForwardExecutor {
  protected static override readonly APPROACH_YAW_EPS = 0.12

  protected override _isYawAlignedForApproach(target: Vec3): boolean {
    return (
      this._yawDeltaAbs(this._desiredYawTo(target)) <=
      LadderLandingDiagonalExecutor.APPROACH_YAW_EPS
    )
  }
}

// Adapted from Rewrite examples/ladders (MIT).
import { JUMP_ONE_BLOCK_COST, COST_INF } from '../costs'
import { Vec3 } from 'vec3'
import * as goals from '../../goals'
import { Move } from '../../move'
import { Movement } from '../movement'
import { MovementProvider } from '../movementProvider'
import { BlockInfo } from '../../world/cacheWorld'

const DIAGONAL_COST = Math.SQRT2

function closedKey(pos: Vec3): string {
  return `${pos.x},${pos.y},${pos.z}`
}

function getLadderSupportCandidates(landing: Vec3, dir: Vec3): Vec3[] {
  const candidates = [landing.offset(-dir.x, -1, -dir.z)]

  if (dir.x !== 0 && dir.z !== 0) {
    candidates.push(landing.offset(-dir.x, -1, 0))
    candidates.push(landing.offset(0, -1, -dir.z))
  } else if (dir.x !== 0) {
    candidates.push(landing.offset(0, -1, 1))
    candidates.push(landing.offset(0, -1, -1))
  } else if (dir.z !== 0) {
    candidates.push(landing.offset(1, -1, 0))
    candidates.push(landing.offset(-1, -1, 0))
  }

  return candidates
}

function getLadderSupport(provider: MovementProvider, landing: Vec3, dir: Vec3): Vec3 | null {
  for (const candidate of getLadderSupportCandidates(landing, dir)) {
    if (provider.getBlockInfoRaw(candidate).climbable) return candidate
  }
  return null
}

function setLadderSupportMetadata(move: Move, ladderSupport: Vec3): void {
  move.metadata = {
    ...move.metadata,
    ladderSupport
  }
}

function pushMoveWithOptionalLadder(
  neighbors: Move[],
  node: Move,
  cost: number,
  landing: Vec3,
  ladderSupport: Vec3 | null,
  moveType: MovementProvider
): void {
  // Normal gap jumps are supplied by the core parkour providers.
  if (ladderSupport == null) return
  cost += moveType.exclusionStep(moveType.getBlockInfoRaw(landing))
  if (cost >= COST_INF) return
  const move = Move.fromPrevious(cost, landing.offset(0.5, 0, 0.5), node, moveType)
  if (ladderSupport != null) setLadderSupportMetadata(move, ladderSupport)
  neighbors.push(move)
}

function pushMoveLandingOnLadder(
  neighbors: Move[],
  node: Move,
  cost: number,
  ladderPos: Vec3,
  moveType: MovementProvider
): void {
  cost += moveType.exclusionStep(moveType.getBlockInfoRaw(ladderPos.offset(0, 1, 0)))
  if (cost >= COST_INF) return
  const move = Move.fromPrevious(cost, ladderPos.offset(0.5, 1, 0.5), node, moveType)
  setLadderSupportMetadata(move, ladderPos)
  neighbors.push(move)
}

/**
 * Ladder-assisted parkour forward movement.
 *
 * This is intentionally kept very close to the existing parkour forward
 * producer so the behavior stays familiar, with the only added rule being that
 * a ladder in the block immediately before the landing can satisfy the higher
 * forward variants.
 */
export class LadderForward extends MovementProvider {
  movementDirs = Movement.cardinalDirs

  provideMovements(start: Move, storage: Move[], goal: goals.Goal, closed: Set<string>): void {
    for (const dir of Movement.cardinalDirs) {
      this.getMoveLadderForward(start, dir, storage, closed)
    }
  }

  /**
   * One-block-down forward jump.
   */
  private canForwardDropLanding(
    ladderAtC: Vec3 | null,
    ceilingClear: boolean,
    distance: number,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    floorCleared: boolean
  ): boolean {
    return (
      floorCleared &&
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.walkthrough &&
      (ceilingClear || distance === 2 || ladderAtC != null)
    )
  }

  /**
   * Flat forward jump.
   */
  private canForwardFlatLanding(
    ladderAtC: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.physical &&
      (ceilingClear || ladderAtC != null)
    )
  }

  /**
   * Two-block-up forward jump.
   */
  private canForwardTwoUpLanding(
    ladderAtA: Vec3 | null,
    ceilingClear: boolean,
    blockA: BlockInfo,
    blockB: BlockInfo
  ): boolean {
    return blockA.walkthrough && blockB.physical && ladderAtA != null && ceilingClear
  }

  /**
   * One-block-up forward jump.
   */
  private canForwardOneUpLanding(
    ladderAtB: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.physical &&
      blockD.walkthrough &&
      (ceilingClear || ladderAtB != null)
    )
  }

  getMoveLadderForward(node: Move, dir: Vec3, neighbors: Move[], closed: Set<string>): void {
    const block0 = this.getBlockInfo(node, 0, -1, 0)

    if (!block0.physical) return

    const block00 = this.getBlockInfo(node, 0, 0, 0)
    if (block00.liquid) return

    const block1 = this.getBlockInfo(node, dir.x, -1, dir.z)
    if (
      (block1.physical && block1.height >= block0.height) ||
      !this.getBlockInfo(node, dir.x, 0, dir.z).walkthrough ||
      !this.getBlockInfo(node, dir.x, 1, dir.z).walkthrough
    ) {
      return
    }

    const cost0 = JUMP_ONE_BLOCK_COST + this.settings.jumpCost
    let ceilingClear =
      this.getBlockInfo(node, 0, 2, 0).walkthrough &&
      this.getBlockInfo(node, dir.x, 2, dir.z).walkthrough
    let floorCleared = !this.getBlockInfo(node, dir.x, -2, dir.z).physical
    const maxD = this.settings.allowSprinting ? 7 : 4

    for (let d = 2; d <= maxD; d++) {
      const cost = cost0 + this.travelCost(d)
      const dx = dir.x * d
      const dz = dir.z * d

      const flag0 = !closed.has(closedKey(new Vec3(node.x + dx, node.y - 1, node.z + dz)))
      const flag1 = !closed.has(closedKey(new Vec3(node.x + dx, node.y, node.z + dz)))
      const flag2 = !closed.has(closedKey(new Vec3(node.x + dx, node.y + 1, node.z + dz)))

      if (!flag0 && !flag1 && !flag2) return

      const blockA = this.getBlockInfo(node, dx, 2, dz)
      const blockB = this.getBlockInfo(node, dx, 1, dz)
      const blockC = this.getBlockInfo(node, dx, 0, dz)
      const blockD = this.getBlockInfo(node, dx, -1, dz)

      const ladderAtC = getLadderSupport(this, blockC.position, dir)
      const ladderAtB = getLadderSupport(this, blockB.position, dir)
      const ladderAtA = getLadderSupport(this, blockA.position, dir)

      if (
        flag0 &&
        this.canForwardDropLanding(ladderAtC, ceilingClear, d, blockB, blockC, blockD, floorCleared)
      ) {
        const blockE = this.getBlockInfo(node, dx, -2, dz)
        if (ladderAtC != null) {
          pushMoveWithOptionalLadder(neighbors, node, cost, blockC.position, ladderAtC, this)
        } else if (blockE.physical) {
          pushMoveWithOptionalLadder(neighbors, node, cost, blockD.position, null, this)
        }
        floorCleared = floorCleared && !blockE.physical
      } else if (
        d <= 6 &&
        flag1 &&
        this.canForwardFlatLanding(ladderAtC, ceilingClear, blockB, blockC, blockD)
      ) {
        pushMoveWithOptionalLadder(neighbors, node, cost + 3, blockC.position, ladderAtC, this)
        break
      } else if (
        d <= 4 &&
        flag2 &&
        this.canForwardTwoUpLanding(ladderAtA, ceilingClear, blockA, blockB)
      ) {
        pushMoveWithOptionalLadder(neighbors, node, cost, blockA.position, ladderAtA, this)
        break
      } else if (
        d <= 6 &&
        flag2 &&
        this.canForwardOneUpLanding(ladderAtB, ceilingClear, blockB, blockC, blockD)
      ) {
        if (d === 5) continue

        if (blockC.height - block0.height > 1.2 && ladderAtB == null) break
        pushMoveWithOptionalLadder(neighbors, node, cost, blockB.position, ladderAtB, this)
        break
      } else if (!blockB.walkthrough || !blockC.walkthrough) {
        break
      }

      ceilingClear = ceilingClear && blockA.walkthrough
    }
  }
}

/**
 * Ladder-assisted parkour diagonal movement.
 *
 * This mirrors the standard diagonal producer and only relaxes the higher path
 * when a ladder is present on the approach block.
 */
export class LadderDiagonal extends MovementProvider {
  movementDirs = Movement.diagonalDirs

  static allowOffsetDiagonals = true

  provideMovements(start: Move, storage: Move[], goal: goals.Goal, closed: Set<string>): void {
    for (const dir of Movement.diagonalDirs) {
      this.getMoveLadderDiagonal(start, dir, storage, closed)
    }
  }

  /**
   * One-block-down diagonal jump.
   */
  private canDiagonalDropLanding(
    ladderAtC: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontD: BlockInfo,
    blockEPhysical: boolean
  ): boolean {
    return (
      blockEPhysical &&
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.walkthrough &&
      blockFrontD.walkthrough &&
      (ceilingClear || ladderAtC != null)
    )
  }

  /**
   * Flat diagonal jump.
   */
  private canDiagonalFlatLanding(
    ladderAtC: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontC: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.physical &&
      blockFrontC.walkthrough &&
      (ceilingClear || ladderAtC != null)
    )
  }

  /**
   * Two-block-up diagonal jump.
   */
  private canDiagonalTwoUpLanding(
    ladderAtA: Vec3 | null,
    ceilingClear: boolean,
    blockA: BlockInfo,
    blockB: BlockInfo
  ): boolean {
    return blockA.walkthrough && blockB.physical && ladderAtA != null && ceilingClear
  }

  /**
   * One-block-up diagonal jump.
   */
  private canDiagonalOneUpLanding(
    ladderAtB: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontB: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.physical &&
      blockD.walkthrough &&
      blockFrontB.walkthrough &&
      (ceilingClear || ladderAtB != null)
    )
  }

  getMoveLadderDiagonal(node: Move, dir: Vec3, neighbors: Move[], closed: Set<string>): void {
    const block0 = this.getBlockInfo(node, 0, -1, 0)
    if (!block0.physical) return

    const block00 = this.getBlockInfo(node, 0, 0, 0)
    if (block00.liquid) return

    const block1Floor = this.getBlockInfo(node, dir.x, -1, dir.z)
    if (block1Floor.physical && block1Floor.height >= block0.height) return

    if (!this.getBlockInfo(node, dir.x, 0, dir.z).walkthrough) return
    if (!this.getBlockInfo(node, dir.x, 1, dir.z).walkthrough) return

    if (!this.getBlockInfo(node, dir.x, 0, 0).walkthrough) return
    if (!this.getBlockInfo(node, 0, 0, dir.z).walkthrough) return
    if (!this.getBlockInfo(node, dir.x, 1, 0).walkthrough) return
    if (!this.getBlockInfo(node, 0, 1, dir.z).walkthrough) return

    const cost0 = JUMP_ONE_BLOCK_COST + this.settings.jumpCost
    const maxD = this.settings.allowSprinting ? 6 : 4

    for (let d = 2; d <= maxD; d++) {
      if (this.tryDiagonalLanding(node, dir, d, d, cost0, block0, neighbors, closed)) break
    }

    if (LadderDiagonal.allowOffsetDiagonals) {
      for (let major = 2; major <= maxD; major++) {
        for (let minor = 1; minor < major; minor++) {
          if (minor === major) continue

          if (this.tryDiagonalLanding(node, dir, minor, major, cost0, block0, neighbors, closed))
            return
          if (this.tryDiagonalLanding(node, dir, major, minor, cost0, block0, neighbors, closed))
            return
        }
      }
    }
  }

  private tryDiagonalLanding(
    node: Move,
    dir: Vec3,
    xSteps: number,
    zSteps: number,
    cost0: number,
    block0: BlockInfo,
    neighbors: Move[],
    closed: Set<string>
  ): boolean {
    const dx = dir.x * xSteps
    const dz = dir.z * zSteps

    const travel = Math.sqrt(xSteps * xSteps + zSteps * zSteps)
    const cost = cost0 + this.travelCost(travel)
    const majorIsX = xSteps > zSteps
    const majorIsZ = zSteps > xSteps
    const frontDx = dx - (majorIsX || xSteps === zSteps ? dir.x : 0)
    const frontDz = dz - (majorIsZ || xSteps === zSteps ? dir.z : 0)

    const flag0 = !closed.has(`${node.x + dx},${node.y - 1},${node.z + dz}`)
    const flag1 = !closed.has(`${node.x + dx},${node.y},${node.z + dz}`)
    const flag2 = !closed.has(`${node.x + dx},${node.y + 1},${node.z + dz}`)

    if (!flag0 && !flag1 && !flag2) return false

    const blockD = this.getBlockInfo(node, dx, -1, dz)
    if (blockD.climbable) return false // no need to consider a movement for a ladder, we'll consider it eventually anyway.

    const blockA = this.getBlockInfo(node, dx, 2, dz)
    const blockB = this.getBlockInfo(node, dx, 1, dz)
    const blockC = this.getBlockInfo(node, dx, 0, dz)
    const blockFrontD = this.getBlockInfo(node, frontDx, -1, frontDz)
    const blockFrontC = this.getBlockInfo(node, frontDx, 0, frontDz)
    const blockFrontB = this.getBlockInfo(node, frontDx, 1, frontDz)

    if (!this.getBlockInfo(node, dx, 0, 0).walkthrough) return false
    if (!this.getBlockInfo(node, 0, 0, dz).walkthrough) return false
    if (!this.getBlockInfo(node, dx, 1, 0).walkthrough) return false
    if (!this.getBlockInfo(node, 0, 1, dz).walkthrough) return false

    const blockE = this.getBlockInfo(node, dx, -2, dz)
    const ladderAtC = getLadderSupport(this, blockC.position, dir)
    const ladderAtB = getLadderSupport(this, blockB.position, dir)
    const ladderAtA = getLadderSupport(this, blockA.position, dir)

    const ceilingClear =
      this.getBlockInfo(node, 0, 2, 0).walkthrough &&
      this.getBlockInfo(node, dx, 2, dz).walkthrough &&
      this.getBlockInfo(node, dx, 2, 0).walkthrough &&
      this.getBlockInfo(node, 0, 2, dz).walkthrough

    const floorCleared = !blockE.physical

    if (
      flag0 &&
      this.canDiagonalDropLanding(
        ladderAtC,
        ceilingClear,
        blockB,
        blockC,
        blockD,
        blockFrontD,
        blockE.physical
      )
    ) {
      if (ladderAtC != null) {
        pushMoveWithOptionalLadder(neighbors, node, cost, blockC.position, ladderAtC, this)
        return true
      }

      if (blockE.physical) {
        pushMoveWithOptionalLadder(neighbors, node, cost, blockD.position, null, this)
        return true
      }
    } else if (
      flag1 &&
      this.canDiagonalFlatLanding(ladderAtC, ceilingClear, blockB, blockC, blockD, blockFrontC)
    ) {
      pushMoveWithOptionalLadder(neighbors, node, cost + 3, blockC.position, ladderAtC, this)
      return true
    } else if (flag2 && this.canDiagonalTwoUpLanding(ladderAtA, ceilingClear, blockA, blockB)) {
      pushMoveWithOptionalLadder(neighbors, node, cost, blockA.position, ladderAtA, this)
      return true
    } else if (
      flag2 &&
      this.canDiagonalOneUpLanding(ladderAtB, ceilingClear, blockB, blockC, blockD, blockFrontB)
    ) {
      if (blockC.height - block0.height > 1.2 && ladderAtB == null) return false
      if (travel > 3.0 && ladderAtB == null) return false
      pushMoveWithOptionalLadder(neighbors, node, cost, blockB.position, ladderAtB, this)
      return true
    }

    return false
  }
}

/**
 * Ladder-landing parkour forward movement.
 *
 * This variant targets the ladder block itself instead of the air block above
 * and behind it.
 */
export class LadderLandingForward extends MovementProvider {
  movementDirs = Movement.cardinalDirs

  provideMovements(start: Move, storage: Move[], goal: goals.Goal, closed: Set<string>): void {
    for (const dir of Movement.cardinalDirs) {
      this.getMoveLadderLandingForward(start, dir, storage, closed)
    }
  }

  private canForwardLandingDrop(
    ladderAtC: Vec3 | null,
    ceilingClear: boolean,
    distance: number,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockEPhysical: boolean
  ): boolean {
    return (
      blockEPhysical &&
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.walkthrough &&
      (ceilingClear || distance === 2 || ladderAtC != null)
    )
  }

  private canForwardLandingFlat(
    ladderAtB: Vec3 | null,
    ceilingClear: boolean,
    blockC: BlockInfo,
    blockD: BlockInfo
  ): boolean {
    return blockC.walkthrough && blockD.physical && (ceilingClear || ladderAtB != null)
  }

  private canForwardLandingTwoUp(
    ladderAtA: Vec3 | null,
    ceilingClear: boolean,
    blockA: BlockInfo,
    blockB: BlockInfo
  ): boolean {
    return blockA.walkthrough && blockB.physical && ladderAtA != null && ceilingClear
  }

  private canForwardLandingOneUp(
    ladderAtB: Vec3 | null,
    ceilingClear: boolean,
    blockC: BlockInfo,
    blockD: BlockInfo
  ): boolean {
    return blockC.physical && blockD.walkthrough && (ceilingClear || ladderAtB != null)
  }

  private getMoveLadderLandingForward(
    node: Move,
    dir: Vec3,
    neighbors: Move[],
    closed: Set<string>
  ): void {
    const block0 = this.getBlockInfo(node, 0, -1, 0)
    if (!block0.physical) return

    const block00 = this.getBlockInfo(node, 0, 0, 0)
    if (block00.liquid) return

    const block1 = this.getBlockInfo(node, dir.x, -1, dir.z)
    if (
      (block1.physical && block1.height >= block0.height) ||
      !this.getBlockInfo(node, dir.x, 0, dir.z).walkthrough ||
      !this.getBlockInfo(node, dir.x, 1, dir.z).walkthrough
    ) {
      return
    }

    const cost0 = JUMP_ONE_BLOCK_COST + this.settings.jumpCost
    const baseCeilingClear = this.getBlockInfo(node, 0, 2, 0).walkthrough
    const maxD = this.settings.allowSprinting ? 7 : 4

    for (let d = 2; d <= maxD; d++) {
      const cost = cost0 + this.travelCost(d)
      const dx = dir.x * d
      const dz = dir.z * d

      const flag0 = !closed.has(closedKey(new Vec3(node.x + dx, node.y - 1, node.z + dz)))
      const flag1 = !closed.has(closedKey(new Vec3(node.x + dx, node.y, node.z + dz)))
      const flag2 = !closed.has(closedKey(new Vec3(node.x + dx, node.y + 1, node.z + dz)))

      if (!flag0 && !flag1 && !flag2) return

      const blockA = this.getBlockInfo(node, dx, 2, dz)
      const blockB = this.getBlockInfo(node, dx, 1, dz)
      const blockC = this.getBlockInfo(node, dx, 0, dz)
      const blockD = this.getBlockInfo(node, dx, -1, dz)
      const blockE = this.getBlockInfo(node, dx, -2, dz)

      const ladderAtC = getLadderSupport(this, blockC.position, dir)
      const ladderAtB = getLadderSupport(this, blockB.position, dir)
      const ladderAtA = getLadderSupport(this, blockA.position, dir)
      const ceilingClear = baseCeilingClear && blockA.walkthrough
      const floorCleared = !blockE.physical

      if (
        flag0 &&
        this.canForwardLandingDrop(ladderAtC, ceilingClear, d, blockB, blockC, blockD, floorCleared)
      ) {
        if (ladderAtC != null) {
          pushMoveLandingOnLadder(neighbors, node, cost, ladderAtC, this)
        }
      } else if (
        d <= 6 &&
        flag1 &&
        this.canForwardLandingFlat(ladderAtB, ceilingClear, blockC, blockD)
      ) {
        if (ladderAtB != null) {
          pushMoveLandingOnLadder(neighbors, node, cost + 3, ladderAtB, this)
        }
        break
      } else if (
        d <= 4 &&
        flag2 &&
        this.canForwardLandingTwoUp(ladderAtA, ceilingClear, blockA, blockB)
      ) {
        pushMoveLandingOnLadder(neighbors, node, cost, ladderAtA!, this)
        break
      } else if (
        d <= 6 &&
        flag2 &&
        this.canForwardLandingOneUp(ladderAtB, ceilingClear, blockC, blockD)
      ) {
        if (blockC.height - block0.height > 1.2 && ladderAtB == null) break
        if (ladderAtB != null) {
          pushMoveLandingOnLadder(neighbors, node, cost, ladderAtB, this)
        }
        break
      } else if (!blockB.walkthrough || !blockC.walkthrough) {
        continue
      }
    }
  }
}

/**
 * Ladder-landing parkour diagonal movement.
 *
 * This variant targets the ladder block itself instead of the air block above
 * and behind it.
 */
export class LadderLandingDiagonal extends MovementProvider {
  movementDirs = Movement.diagonalDirs

  static allowOffsetDiagonals = true

  provideMovements(start: Move, storage: Move[], goal: goals.Goal, closed: Set<string>): void {
    for (const dir of Movement.diagonalDirs) {
      this.getMoveLadderLandingDiagonal(start, dir, storage, closed)
    }
  }

  private canDiagonalLandingDrop(
    ladderAtC: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontD: BlockInfo,
    blockEPhysical: boolean
  ): boolean {
    return (
      blockEPhysical &&
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.walkthrough &&
      blockFrontD.walkthrough &&
      (ceilingClear || ladderAtC != null)
    )
  }

  private canDiagonalLandingFlat(
    ladderAtB: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontC: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.walkthrough &&
      blockD.physical &&
      blockFrontC.walkthrough &&
      (ceilingClear || ladderAtB != null)
    )
  }

  private canDiagonalLandingTwoUp(
    ladderAtA: Vec3 | null,
    ceilingClear: boolean,
    blockA: BlockInfo,
    blockB: BlockInfo
  ): boolean {
    return blockA.walkthrough && blockB.physical && ladderAtA != null && ceilingClear
  }

  private canDiagonalLandingOneUp(
    ladderAtB: Vec3 | null,
    ceilingClear: boolean,
    blockB: BlockInfo,
    blockC: BlockInfo,
    blockD: BlockInfo,
    blockFrontB: BlockInfo
  ): boolean {
    return (
      blockB.walkthrough &&
      blockC.physical &&
      blockD.walkthrough &&
      blockFrontB.walkthrough &&
      (ceilingClear || ladderAtB != null)
    )
  }

  private getMoveLadderLandingDiagonal(
    node: Move,
    dir: Vec3,
    neighbors: Move[],
    closed: Set<string>
  ): void {
    const block0 = this.getBlockInfo(node, 0, -1, 0)
    if (!block0.physical) return

    const block00 = this.getBlockInfo(node, 0, 0, 0)
    if (block00.liquid) return

    const block1Floor = this.getBlockInfo(node, dir.x, -1, dir.z)
    if (block1Floor.physical && block1Floor.height >= block0.height) return

    if (!this.getBlockInfo(node, dir.x, 0, dir.z).walkthrough) return
    if (!this.getBlockInfo(node, dir.x, 1, dir.z).walkthrough) return
    if (!this.getBlockInfo(node, dir.x, 0, 0).walkthrough) return
    if (!this.getBlockInfo(node, 0, 0, dir.z).walkthrough) return
    if (!this.getBlockInfo(node, dir.x, 1, 0).walkthrough) return
    if (!this.getBlockInfo(node, 0, 1, dir.z).walkthrough) return

    const cost0 = JUMP_ONE_BLOCK_COST + this.settings.jumpCost
    const maxD = this.settings.allowSprinting ? 6 : 4

    for (let d = 2; d <= maxD; d++) {
      if (this.tryDiagonalLanding(node, dir, d, d, cost0, block0, neighbors, closed)) break
    }

    if (LadderLandingDiagonal.allowOffsetDiagonals) {
      for (let major = 2; major <= maxD; major++) {
        for (let minor = 1; minor < major; minor++) {
          if (minor === major) continue

          if (this.tryDiagonalLanding(node, dir, minor, major, cost0, block0, neighbors, closed))
            return
          if (this.tryDiagonalLanding(node, dir, major, minor, cost0, block0, neighbors, closed))
            return
        }
      }
    }
  }

  private tryDiagonalLanding(
    node: Move,
    dir: Vec3,
    xSteps: number,
    zSteps: number,
    cost0: number,
    block0: BlockInfo,
    neighbors: Move[],
    closed: Set<string>
  ): boolean {
    const dx = dir.x * xSteps
    const dz = dir.z * zSteps

    const travel = Math.sqrt(xSteps * xSteps + zSteps * zSteps)
    const cost = cost0 + this.travelCost(travel)
    const majorIsX = xSteps > zSteps
    const majorIsZ = zSteps > xSteps
    const frontDx = dx - (majorIsX || xSteps === zSteps ? dir.x : 0)
    const frontDz = dz - (majorIsZ || xSteps === zSteps ? dir.z : 0)

    const flag0 = !closed.has(closedKey(new Vec3(node.x + dx, node.y - 1, node.z + dz)))
    const flag1 = !closed.has(closedKey(new Vec3(node.x + dx, node.y, node.z + dz)))
    const flag2 = !closed.has(closedKey(new Vec3(node.x + dx, node.y + 1, node.z + dz)))

    if (!flag0 && !flag1 && !flag2) return false

    const blockD = this.getBlockInfo(node, dx, -1, dz)
    if (blockD.climbable) return false

    const blockA = this.getBlockInfo(node, dx, 2, dz)
    const blockB = this.getBlockInfo(node, dx, 1, dz)
    const blockC = this.getBlockInfo(node, dx, 0, dz)
    const blockFrontD = this.getBlockInfo(node, frontDx, -1, frontDz)
    const blockFrontC = this.getBlockInfo(node, frontDx, 0, frontDz)
    const blockFrontB = this.getBlockInfo(node, frontDx, 1, frontDz)

    if (!this.getBlockInfo(node, dx, 0, 0).walkthrough) return false
    if (!this.getBlockInfo(node, 0, 0, dz).walkthrough) return false
    if (!this.getBlockInfo(node, dx, 1, 0).walkthrough) return false
    if (!this.getBlockInfo(node, 0, 1, dz).walkthrough) return false

    const blockE = this.getBlockInfo(node, dx, -2, dz)
    const ladderAtC = getLadderSupport(this, blockC.position, dir)
    const ladderAtB = getLadderSupport(this, blockB.position, dir)
    const ladderAtA = getLadderSupport(this, blockA.position, dir)

    const ceilingClear =
      this.getBlockInfo(node, 0, 2, 0).walkthrough &&
      this.getBlockInfo(node, dx, 2, dz).walkthrough &&
      this.getBlockInfo(node, dx, 2, 0).walkthrough &&
      this.getBlockInfo(node, 0, 2, dz).walkthrough

    if (
      flag0 &&
      this.canDiagonalLandingDrop(
        ladderAtC,
        ceilingClear,
        blockB,
        blockC,
        blockD,
        blockFrontD,
        blockE.physical
      )
    ) {
      if (ladderAtC != null) {
        pushMoveLandingOnLadder(neighbors, node, cost, ladderAtC, this)
        return true
      }
    } else if (
      flag1 &&
      this.canDiagonalLandingFlat(ladderAtB, ceilingClear, blockB, blockC, blockD, blockFrontC)
    ) {
      if (ladderAtB != null) {
        pushMoveLandingOnLadder(neighbors, node, cost + 3, ladderAtB, this)
        return true
      }
    } else if (flag2 && this.canDiagonalLandingTwoUp(ladderAtA, ceilingClear, blockA, blockB)) {
      pushMoveLandingOnLadder(neighbors, node, cost, ladderAtA!, this)
      return true
    } else if (
      flag2 &&
      this.canDiagonalLandingOneUp(ladderAtB, ceilingClear, blockB, blockC, blockD, blockFrontB)
    ) {
      if (blockC.height - block0.height > 1.2 && ladderAtB == null) return false
      if (travel > 3.0 && ladderAtB == null) return false
      if (ladderAtB != null) {
        pushMoveLandingOnLadder(neighbors, node, cost, ladderAtB, this)
        return true
      }
    }

    return false
  }
}

import { Vec3 } from 'vec3'
import { Move } from '../../move'
import { MovementProvider } from '../movementProvider'
import { Goal } from '../../goals'
import { canUseFrostWalker, canWalkOn, canWalkThrough, findPlaceOpts, getMiningDurationTicks, isBottomSlab } from './movementHelper'
import { BreakHandler, PlaceHandler } from '../interactionUtils'
import { CENTER_AFTER_FALL_COST, COST_INF, FALL_N_BLOCKS_COST, JUMP_ONE_BLOCK_COST, WALK_OFF_BLOCK_COST, WALK_ONE_BLOCK_COST, WALK_ONE_OVER_SOUL_SAND_COST } from '../costs'
import { BlockInfo } from '../../world/cacheWorld'

export class IdleMovement extends MovementProvider {
  movementDirs: Vec3[] = []
  provideMovements (start: Move, storage: Move[]): void {}
  async performInit (thisMove: Move, currentIndex: number, path: Move[]): Promise<void> {}
  async performPerTick (thisMove: Move, tickCount: number, currentIndex: number, path: Move[]): Promise<boolean> {
    return true
  }
}

// base all code in this file off of:
// https://github.com/cabaletta/baritone/blob/1.19.4/src/main/java/baritone/pathing/movement/movements/MovementAscend.java

export class MovementAscend extends MovementProvider {
  movementDirs = [new Vec3(0, 1, 0)]
  provideMovements (start: Move, storage: Move[], goal: Goal, closed: Set<string>): void {
    for (const dir of this.movementDirs) {
      const off = start.cachedVec.plus(dir)
      if (closed.has(off.toString())) return
      this.provideAscend(start, dir, storage, closed)
    }
  }

  provideAscend (node: Move, dir: Vec3, storage: Move[], closed: Set<string>): void {
    const blPlace = this.getBlockInfo(node, dir.x, 0, dir.y)

    if (blPlace.isInvalid) return

    // potentially get rid of these, as we don't actually need them for the time being.
    const toPlace: PlaceHandler[] = []
    const toBreak: BreakHandler[] = []

    let cost = 0
    if (!blPlace.physical) {
      if (!blPlace.replaceable) {
        if ((cost += this.safeOrBreak(blPlace, toBreak)) >= COST_INF) return
      }
      if ((cost += this.safeOrPlace(blPlace, toPlace)) >= COST_INF) return
      if (findPlaceOpts(this, node, blPlace.position) == null) return
    }

    const srcUp1 = this.getBlockInfo(node, 0, 1, 0)
    const srcUp2 = this.getBlockInfo(node, 0, 2, 0)
    const srcUp3 = this.getBlockInfo(node, 0, 3, 0)
    // translate below to typescript
    //         if (context.get(x, y + 3, z).getBlock() instanceof FallingBlock && (MovementHelper.canWalkThrough(context, x, y + 1, z) || !(srcUp2.getBlock() instanceof FallingBlock))) {//it would fall on us and possibly suffocate us

    if (srcUp3.canFall && (canWalkThrough(srcUp1) || !srcUp2.canFall)) {
      return
    }

    const srcDown1 = this.getBlockInfo(node, 0, -1, 0)
    if (srcDown1.climbable) return

    const jumpFromBottomSlab = isBottomSlab(srcDown1)
    const jumpToBottomSlab = isBottomSlab(blPlace)

    if (jumpFromBottomSlab && !jumpToBottomSlab) {
      return
    }

    let walk = 0
    if (jumpToBottomSlab) {
      if (jumpFromBottomSlab) {
        walk = Math.max(JUMP_ONE_BLOCK_COST, WALK_ONE_BLOCK_COST) // we hit space immediately on entering this action
        walk += this.settings.jumpCost
      } else {
        walk = WALK_ONE_BLOCK_COST
      }
    } else {
      // for speed
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      if (blPlace.block!.type === BlockInfo.soulsandId) {
        walk = WALK_ONE_OVER_SOUL_SAND_COST
      } else {
        walk = Math.max(JUMP_ONE_BLOCK_COST, WALK_ONE_BLOCK_COST)
      }
      walk += this.settings.jumpCost
    }

    if ((cost += walk) >= COST_INF) return
    if ((cost += getMiningDurationTicks(this, srcUp2)) >= COST_INF) return

    const target1 = this.getBlockInfo(node, dir.x, 1, dir.z)
    if ((cost += getMiningDurationTicks(this, target1)) >= COST_INF) return

    const target2 = this.getBlockInfo(node, dir.x, 2, dir.z)
    if ((cost += getMiningDurationTicks(this, target2)) >= COST_INF) return

    cost += 1
  }
}

export class MovementDescend extends MovementProvider {
  movementDirs = [new Vec3(0, -1, 0)]
  provideMovements (start: Move, storage: Move[], goal: Goal, closed: Set<string>): void {
    for (const dir of this.movementDirs) {
      this.provideDescend(start, dir, storage, closed)
    }
  }

  provideDescend (node: Move, dir: Vec3, storage: Move[], closed: Set<string>): void {
    const srcN1 = this.getBlockInfo(node, dir.x, -1, dir.z)
    if (srcN1.climbable) return

    const srcN2 = this.getBlockInfo(node, dir.x, -2, dir.z)
    if (!canWalkOn(srcN2)) {
      return // for now, do not calculate this movement as it will be handled by movementFall.
      // this.dynamicFallCosts(srcN2, cost);
    }

    if (canUseFrostWalker(this, srcN2)) {
      return
    }

    let cost = 0

    const destN1 = this.getBlockInfo(node, dir.x, -1, dir.z)
    if ((cost += getMiningDurationTicks(this, destN1)) >= COST_INF) return

    const dest = this.getBlockInfo(node, dir.x, 0, dir.z)
    if ((cost += getMiningDurationTicks(this, dest)) >= COST_INF) return

    const dest1 = this.getBlockInfo(node, dir.x, 1, dir.z)
    if ((cost += getMiningDurationTicks(this, dest1, true)) >= COST_INF) return

    let walk = WALK_OFF_BLOCK_COST

    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    if (srcN1.block!.type === BlockInfo.soulsandId) {
      walk = WALK_ONE_OVER_SOUL_SAND_COST / WALK_ONE_BLOCK_COST
    }

    cost += walk
    cost += Math.max(FALL_N_BLOCKS_COST[1], CENTER_AFTER_FALL_COST)
  }

  // TODO: implement mutables
  dynamicFallCosts (info: BlockInfo, cost: number): void {

  }
}

export class MovementDiagonal extends MovementProvider {
  movementDirs = MovementProvider.diagonalDirs
  provideMovements (start: Move, storage: Move[], goal: Goal, closed: Set<string>): void {

  }
}

import { Vec3 } from 'vec3'
import { BlockInfo } from '../../world/cacheWorld'
import { Movement } from '../movement'
import { Vec3Properties } from '../../../types'

export function canWalkOn (info: BlockInfo): boolean {
  if (info.block == null) return false
  return info.block.boundingBox === 'block' || info.safe
}

export function canWalkThrough (info: BlockInfo): boolean {
  if (info.block == null) return false
  return info.block.boundingBox === 'empty' || info.safe
}

const ALL_DIRS_BUT_UP = [
  new Vec3(1, 0, 0),
  new Vec3(-1, 0, 0),
  new Vec3(0, 0, 1),
  new Vec3(0, 0, -1),
  new Vec3(0, -1, 0)
]
export function findPlaceOpts (move: Movement, orgPos: Vec3Properties, pos: Vec3Properties): BlockInfo | null {
  for (const dir of ALL_DIRS_BUT_UP) {
    const nX = pos.x + dir.x
    const nZ = pos.z + dir.z
    if (nX === orgPos.x && nZ === orgPos.z) continue
    const info = move.getBlockInfo(pos, dir.x, dir.y, dir.z)
    if (canPlaceAgainst(info)) return info
  }

  return null
}

export function canPlaceAgainst (info: BlockInfo): boolean {
  return info.physical
}

export function isBottomSlab (info: BlockInfo): boolean {
  return info.dY === 0.5
}

export function getMiningDurationTicks (move: Movement, info: BlockInfo, includeFalling = false): number {
  if (!includeFalling) return move.breakCost(info)

  const above = move.getBlockInfo(info.position, 0, 1, 0)
  return move.breakCost(info) + getMiningDurationTicks(move, above, true) // recurse upwards. potentially slow.
}

export function getMiningDurationTicksCoords (move: Movement, pos: Vec3, includeFalling = false): number {
  return getMiningDurationTicks(move, move.getBlockInfoRaw(pos), includeFalling)
}

export function canUseFrostWalker (move: Movement, info: BlockInfo): boolean {
  return info.liquid && false // TODO: frostwalker.
}

// SPDX-License-Identifier: GPL-3.0-only
// TypeScript adaptation of Botcraft PathfindingTask.cpp vertical movement and
// AdjustPosSpeed (https://github.com/adepierre/Botcraft). Modified for Mineflayer.
import { Vec3 } from 'vec3'
import { Move } from '../move'
import { Movement } from './movement'
import { MovementProvider } from './movementProvider'
import { MovementExecutor } from './movementExecutor'
import { Goal } from '../goals'
import { COST_INF, LADDER_UP_ONE_COST, LADDER_DOWN_ONE_COST } from './costs'
import { CancelError } from '../exceptions'
import { steerToPosition } from './controls'

const entryDirs = [...Movement.cardinalDirs, ...Movement.diagonalDirs]

/** Climbable cells support the player without a solid floor, as in Botcraft. */
export class Climb extends MovementProvider {
  movementDirs = Movement.cardinalDirs

  provideMovements (start: Move, storage: Move[], goal: Goal, closed: Set<string>): void {
    const feet = this.getBlockInfo(start, 0, 0, 0)
    const below = this.getBlockInfo(start, 0, -1, 0)
    const push = (offset: Vec3, mode: string): void => {
      const dest = start.cachedVec.plus(offset)
      if (closed.has(`${dest.x},${dest.y},${dest.z}`)) return
      const foot = this.getBlockInfoRaw(dest)
      const head = this.getBlockInfoRaw(dest.offset(0, 1, 0))
      if (foot.isInvalid || head.isInvalid || !foot.walkthrough || !head.walkthrough || !foot.safe || !head.safe) return
      const exclusion = this.exclusionStep(foot)
      if (exclusion >= COST_INF) return
      const travel = offset.y > 0 ? LADDER_UP_ONE_COST : offset.y < 0 ? LADDER_DOWN_ONE_COST : this.travelCost(Math.hypot(offset.x, offset.z))
      const move = Move.fromPrevious(travel + exclusion,
        dest.offset(0.5, 0, 0.5), start, this)
      move.metadata = { climbMode: mode }
      storage.push(move)
    }

    if (feet.climbable) {
      // Stay attached throughout ascent. The last ascent is combined with the
      // lateral exit, avoiding a fictitious stop in air above the ladder.
      if (this.getBlockInfo(start, 0, 1, 0).climbable) push(new Vec3(0, 1, 0), 'up')
      // A ladder's thin collision shape supports a final stop on its top. This
      // lets us jump onto a wall one block above the final rung, as in Botcraft.
      else if (feet.block?.name === 'ladder' && feet.dY === 1) push(new Vec3(0, 1, 0), 'crest')
      if (below.climbable || (below.walkthrough && this.getBlockInfo(start, 0, -2, 0).physical)) push(new Vec3(0, -1, 0), 'down')
      for (const dir of this.movementDirs) {
        const support = this.getBlockInfo(start, dir.x, 0, dir.z)
        if (support.solidFull && this.getBlockInfo(start, 0, 2, 0).walkthrough) push(dir.offset(0, 1, 0), 'exit')
        if (this.getBlockInfo(start, dir.x, -1, dir.z).solidFull) push(dir, 'exit')
      }
    } else if (below.climbable && feet.walkthrough) {
      push(new Vec3(0, -1, 0), 'down')
    }

    // Head-height ladders can be grabbed with a normal jump from solid ground.
    if (!feet.climbable && below.physical && this.getBlockInfo(start, 0, 1, 0).climbable) push(new Vec3(0, 1, 0), 'enter-up')

    for (const dir of entryDirs) {
      if (dir.x !== 0 && dir.z !== 0) {
        if (!this.getBlockInfo(start, dir.x, 0, 0).walkthrough || !this.getBlockInfo(start, dir.x, 1, 0).walkthrough ||
          !this.getBlockInfo(start, 0, 0, dir.z).walkthrough || !this.getBlockInfo(start, 0, 1, dir.z).walkthrough) continue
      }
      if (this.getBlockInfo(start, dir.x, 0, dir.z).climbable) push(dir, 'enter')
      else if (this.getBlockInfo(start, dir.x, -1, dir.z).climbable) push(dir.offset(0, -1, 0), 'enter')
      else if (below.physical && this.getBlockInfo(start, 0, 2, 0).walkthrough &&
        this.getBlockInfo(start, dir.x, 0, dir.z).walkthrough && this.getBlockInfo(start, dir.x, 1, dir.z).climbable) push(dir.offset(0, 1, 0), 'enter-up')
    }
  }
}

/** Tick-driven translation of Botcraft's Move and AdjustPosSpeed; never waits for ground while climbing. */
export class ClimbExecutor extends MovementExecutor {
  private leaving = false
  private started = 0

  override reset (): void { this.leaving = false; this.started = 0; super.reset() }
  override isAlreadyCompleted (move: Move): boolean { return this.reached(move) }
  align (): boolean { return true }
  performInit (): void { this.started = performance.now() }

  private reached (move: Move): boolean {
    const pos = this.bot.entity.position
    const attached = this.getBlockInfoRaw(pos).climbable
    if (move.metadata?.climbMode === 'crest') return this.bot.entity.onGround && pos.y >= move.exitPos.y - 0.02 && pos.xzDistanceTo(move.exitPos) < 0.24
    if (move.metadata?.climbMode === 'exit') return this.bot.entity.onGround && pos.y >= move.exitPos.y - 0.02 && pos.xzDistanceTo(move.exitPos) < 0.4
    const dy = move.exitPos.y - move.entryPos.y
    const heightReached = dy > 0 ? pos.y >= move.exitPos.y : dy < 0 ? pos.y <= move.exitPos.y + 0.1 : Math.abs(pos.y - move.exitPos.y) < 0.2
    return pos.xzDistanceTo(move.exitPos) < 0.22 && heightReached && (attached || this.bot.entity.onGround)
  }

  // Botcraft projects the error and velocity onto the forward/left axes. This
  // keeps a fixed climbing yaw and corrects drift with strafing, not head spins.
  public adjustPosition (target: Vec3, limit = 0.1): void {
    steerToPosition(this.bot, target, limit)
  }

  private columnAnchor (target: Vec3, mode: unknown): Vec3 {
    let block = this.getBlockInfoRaw(target).block
    if (block?.name !== 'ladder') block = this.getBlockInfoRaw(target.offset(0, -1, 0)).block
    if (block?.name !== 'ladder') return target
    const facing = block.getProperties().facing
    const away: Record<string, Vec3> = { west: new Vec3(-0.16, 0, 0), east: new Vec3(0.16, 0, 0), north: new Vec3(0, 0, -0.16), south: new Vec3(0, 0, 0.16) }
    // Clear the ladder's thin top collision shape before descending, while the
    // feet remain inside its climbable cell. Otherwise the player stands on it.
    const outward = away[String(facing)] ?? new Vec3(0, 0, 0)
    // For a crest, overlap the rung's top instead of stepping off into air.
    return mode === 'crest' ? target.minus(outward) : mode === 'down' ? target.plus(outward) : target
  }

  async performPerTick (move: Move): Promise<boolean> {
    if (this.reached(move)) {
      this.bot.clearControlStates()
      // Sneak arrests downward velocity when the next climbing step is prepared.
      this.bot.setControlState('sneak', !this.bot.entity.onGround)
      return true
    }
    if (performance.now() - this.started > this.settings.movementTimeoutMs + 1000) throw new CancelError('Climbing failed to reach the next step')
    const pos = this.bot.entity.position
    const mode = move.metadata?.climbMode
    const up = mode === 'up' || mode === 'enter-up' || mode === 'crest' || (mode === 'exit' && move.exitPos.y > move.entryPos.y)
    const target = mode === 'exit' && up && !this.leaving ? move.entryPos : move.exitPos
    if (mode === 'exit' && up && pos.y >= move.exitPos.y - 0.01) this.leaving = true
    const aim = mode === 'enter' || mode === 'enter-up' || mode === 'exit' ? move.exitPos : (this.bot.pathfinder.currentPath?.slice(this.bot.pathfinder.currentIndex + 1).find(m => m.exitPos.xzDistanceTo(pos) > 0.7)?.exitPos)
    if (aim != null && aim.xzDistanceTo(pos) > 0.3) await this.lookAtPathPos(aim)
    this.adjustPosition(this.leaving ? move.exitPos : this.columnAnchor(target, move.exitPos.y < move.entryPos.y ? 'down' : mode))
    this.bot.setControlState('sprint', false)
    this.bot.setControlState('sneak', false)
    this.bot.setControlState('jump', up && (!this.leaving || pos.y < move.exitPos.y))
    if (pos.y < Math.min(move.entryPos.y, move.exitPos.y) - 1.25) throw new CancelError('Lost the climbable column')
    return false
  }
}

