/**
 * control strafing left-to-right dependent on offset to current goal.
 * @param nextPoint
 * @returns
 */
// currentPoint: Vec3
export function strafeMovement (ctx: IEntityState, nextPoint: Vec3, strict = false, minDist = 0.1): void {
  applyStrafeMovement(
    {
      pos: ctx.pos,
      vel: ctx.vel,
      yaw: ctx.yaw,
      onGround: ctx.onGround
    },
    nextPoint,
    strict,
    (name, value) => ctx.control.set(name, value),
    (name) => ctx.control.get(name),
    minDist
  )
}

/**
 * control strafing left-to-right dependent on offset to current goal.
 * @param nextPoint
 * @returns
 */
// currentPoint,
export function botStrafeMovement (bot: Bot, nextPoint: Vec3, strict = false, minDist = 0.1): void {
  applyStrafeMovement(
    {
      pos: bot.entity.position,
      vel: bot.entity.velocity,
      yaw: bot.entity.yaw,
      onGround: bot.entity.onGround
    },
    nextPoint,
    strict,
    (name, value) => bot.setControlState(name, value),
    (name) => bot.getControlState(name),
    minDist
  )
}

/**
 * Dependent on offset to current goal, control forward/backward movement.
 * Used in tandem with strafe aim.
 * @param goal
 * @param sprint
 * @returns
 */
// currentPoint,
export function smartMovement (ctx: IEntityState, nextPoint: Vec3, sprint = true, minDist = 0.1): void {
  // console.log('hey!')
  const diff = findDiff(ctx.pos, ctx.vel, ctx.yaw, ctx.pitch, nextPoint, ctx.onGround)

  // console.log(diff)

  if (ctx.pos.distanceTo(nextPoint) < minDist) {
    logStrafe('stopping since near goal')
    ctx.control.set('forward', false)
    ctx.control.set('back', false)
    return
  }

  // const lookDiff = wrapRadians(wrapRadians(ctx.yaw))

  // diff = wrapRadians(diff + lookDiff)

  // console.log('forward/back diff', diff, diff / Math.PI * 12)

  if (EIGHT_PI_OVER_TWELVE < diff && diff < SIXTEEN_PI_OVER_TWELVE) {
    // console.log('going back')
    ctx.control.set('forward', false)
    ctx.control.set('sprint', false)
    ctx.control.set('back', true)

    // console.log("back");
  } else if (TWENTY_PI_OVER_TWELVE < diff || diff < FOUR_PI_OVER_TWELVE) {
    // console.log('going forward')
    ctx.control.set('forward', true)
    ctx.control.set('sprint', sprint)
    ctx.control.set('back', false)
  } else {
    // console.log('going neither')
    ctx.control.set('forward', false)
    ctx.control.set('sprint', false)
    ctx.control.set('back', false)
  }
}

/**
 *
 * @param bot
 * @param goal
 * @param sprint
 * @returns
 */
// currentPoint,
export function botSmartMovement (bot: Bot, nextPoint: Vec3, sprint: boolean, minDist = 0.1): void {
  const stateLike = {
    pos: bot.entity.position,
    vel: bot.entity.velocity,
    yaw: bot.entity.yaw,
    pitch: bot.entity.pitch,
    onGround: bot.entity.onGround,
    control: { set: (name: string, value: boolean) => bot.setControlState(name as any, value) }
  } as IEntityState

  smartMovement(stateLike, nextPoint, sprint, minDist)
}

interface StrafeState {
  pos: Vec3
  vel: Vec3
  yaw: number
  onGround: boolean
}

type StrafeSetter = (name: 'left' | 'right', value: boolean) => void
type StrafeGetter = (name: 'left' | 'right') => boolean

function applyStrafeMovement (state: StrafeState, nextPoint: Vec3, strict: boolean, set: StrafeSetter, get?: StrafeGetter, minDist = 0.1): void {
  if (strict) {
    const dx = nextPoint.x - state.pos.x
    const dz = nextPoint.z - state.pos.z

    const sin = Math.sin(state.yaw)
    const cos = Math.cos(state.yaw)

    const forwardError = -(dx * sin + dz * cos)
    const sideError = dx * cos - dz * sin
    const sideVel = state.vel.x * cos - state.vel.z * sin

    const dist = state.pos.distanceTo(nextPoint)
    if (dist < minDist) {
      set('left', false)
      set('right', false)
      return
    }

    if (forwardError <= 0) {
      set('left', false)
      set('right', false)
      return
    }

    const startThresh = state.onGround ? 0.08 : 0.04
    const stopThresh = state.onGround ? 0.03 : 0.02

    const predictedSideError = sideError - sideVel * 3.0

    // If we are already strafing, keep going until we are close to centered.
    // This avoids rapid oscillation at the threshold.
    const currentlyLeft = get?.('left') ?? false
    const currentlyRight = get?.('right') ?? false

    logStrafe(
      'strict state pos=%O vel=%O yaw=%d target=%O dist=%d forwardError=%d sideError=%d sideVel=%d predictedSideError=%d onGround=%s left=%s right=%s',
      state.pos,
      state.vel,
      state.yaw,
      nextPoint,
      dist,
      forwardError,
      sideError,
      sideVel,
      predictedSideError,
      state.onGround,
      currentlyLeft,
      currentlyRight
    )

    if (currentlyLeft) {
      if (predictedSideError >= -stopThresh) {
        set('left', false)
        logStrafe('strict branch: clear left at stopThresh=%d', stopThresh)
      }
      set('right', false)
      logStrafe('strict branch: hold left=false right=false from left latch')
      return
    }

    if (currentlyRight) {
      if (predictedSideError <= stopThresh) {
        set('right', false)
        logStrafe('strict branch: clear right at stopThresh=%d', stopThresh)
      }
      set('left', false)
      logStrafe('strict branch: hold left=false %s from right latch', predictedSideError > stopThresh ? 'right=true' : 'right=false')
      return
    }

    if (predictedSideError > startThresh) {
      set('left', false)
      set('right', true)
      logStrafe('strict branch: set right=true startThresh=%d', startThresh)
    } else if (predictedSideError < -startThresh) {
      set('left', true)
      set('right', false)
      logStrafe('strict branch: set left=true startThresh=%d', startThresh)
    } else {
      set('left', false)
      set('right', false)
      logStrafe('strict branch: clear lateral controls startThresh=%d', startThresh)
    }
    return
  }

  const diff = findDiff(state.pos, state.vel, state.yaw, 0, nextPoint, state.onGround)

  logStrafe('left/right diff:', diff, diff / Math.PI * 12)

  if (state.pos.distanceTo(nextPoint) < minDist) {
    set('left', false)
    set('right', false)
    return
  }

  if (FOURTEEN_PI_OVER_TWELVE < diff && diff < TWENTY_TWO_PI_OVER_TWELVE) {
    set('left', false)
    set('right', true)
  } else if (TWO_PI_OVER_TWELVE < diff && diff < TEN_PI_OVER_TWELVE) {
    set('left', true)
    set('right', false)
  } else {
    set('left', false)
    set('right', false)
  }
}

// ===========================================================================
// Movement cost constants — every value below is measured in GAME TICKS.
//
// Minecraft runs at 20 ticks per second, so "ticks" is just "how long the bot
// is busy doing this thing". Lower = faster. Putting every cost in the same
// unit (ticks) is the whole point of this file: the pathfinder can now compare
// "walk around" vs "dig through" vs "jump up" honestly, because they are all
// expressed as time, not as made-up numbers.
//
// The numbers are Baritone's hardcoded estimates. Each one is `20 / speed`,
// where `speed` is how many blocks per second the bot covers doing that action
// (e.g. the player walks at 4.317 blocks/s, so walking one block ~ 20 / 4.317
// ~ 4.633 ticks). They are "correct enough" — close to in-game reality without
// running a physics simulation for every candidate move.
// ===========================================================================

/** Ticks to WALK one block (player walks 4.317 blocks/s). */
export const WALK_ONE_BLOCK_COST = 4.633 as const
/** Ticks to swim/walk one block while IN water (much slower than on land). */
export const WALK_ONE_IN_WATER_COST = 9.091 as const
/** Ticks to walk one block on top of soul sand (it drags you). */
export const WALK_ONE_OVER_SOUL_SAND_COST = 9.266 as const
/** Ticks to climb UP one block on a ladder/vine. */
export const LADDER_UP_ONE_COST = 8.511 as const
/** Ticks to climb DOWN one block on a ladder/vine. */
export const LADDER_DOWN_ONE_COST = 6.667 as const
/** Ticks to sneak one block (slowest way to move). */
export const SNEAK_ONE_BLOCK_COST = 15.385 as const
/** Ticks to SPRINT one block (player sprints 5.612 blocks/s — the fastest ground travel). */
export const SPRINT_ONE_BLOCK_COST = 3.564 as const
/** Sprinting is this fraction of the time of walking (sprint / walk). */
export const SPRINT_MULTIPLIER = 0.769 as const
/** Ticks to walk OFF the edge of a block (start of a drop; slightly cheaper than a full walk). */
export const WALK_OFF_BLOCK_COST = 3.706 as const
/** Ticks to re-center on the block you just dropped onto. */
export const CENTER_AFTER_FALL_COST = 0.927 as const
/** "Infinitely expensive" — any move costing this much or more is treated as impossible. */
export const COST_INF = 1000000

/**
 * Per-block weight used by the goal HEURISTIC (A*'s estimate of remaining cost),
 * also measured in ticks. It is deliberately the WALK cost, not the cheaper
 * SPRINT cost.
 *
 * Why walk and not sprint? A* stays optimal only when the heuristic never
 * over-estimates the *cheapest* real cost (sprinting). By estimating with the
 * slightly-higher walk cost we run a lightly "weighted" A*: it leans toward the
 * goal and explores far fewer dead-ends (fast), while the paths it returns are
 * at most ~1.3x the true optimum (walk / sprint = 4.633 / 3.564). Before this
 * file's costs were in ticks, the same heuristic was ~4.6x the per-move cost,
 * so that bound used to be ~4.6x — this is a large quality win at no speed cost.
 */
export const COST_HEURISTIC = 20 / 4.317

/**
 * Lookup table: `FALL_N_BLOCKS_COST[n]` = ticks to fall `n` blocks straight down.
 * Falling speeds up over time, so this is not linear (falling 2 blocks costs less
 * than twice falling 1). Index it with a whole number of blocks.
 */
export const FALL_N_BLOCKS_COST = generateFallNBlocksCost()
export const FALL_1_25_BLOCKS_COST = distanceToTicks(1.25)
export const FALL_0_25_BLOCKS_COST = distanceToTicks(0.25)
/**
 * Ticks for the upward arc of a normal jump. A jump lifts the bot ~1.25 blocks
 * and it lands back ~0.25 blocks lower than the peak, so the "useful" climb costs
 * the difference between those two fall times.
 */
export const JUMP_ONE_BLOCK_COST = FALL_1_25_BLOCKS_COST - FALL_0_25_BLOCKS_COST

/** Rise to the jump apex, then land one block higher (not just the ascent interval). */
export const JUMP_UP_ONE_BLOCK_COST = FALL_1_25_BLOCKS_COST + FALL_0_25_BLOCKS_COST

export function distanceToTicks (distance: number): number {
  if (distance === 0) {
    return 0
  }
  let tmpDistance = distance
  let tickCount = 0
  while (true) {
    const fallDistance = velocity(tickCount)
    if (tmpDistance <= fallDistance) {
      return tickCount + tmpDistance / fallDistance
    }
    tmpDistance -= fallDistance
    tickCount++
  }
}

export function velocity (ticks: number): number {
  return (Math.pow(0.98, ticks) - 1) * -3.92
}

export function oldFormula (ticks: number): number {
  return -3.92 * (99 - 49.5 * (Math.pow(0.98, ticks) + 1) - ticks)
}

export function generateFallNBlocksCost (): number[] {
  const costs: number[] = []
  for (let i = 0; i < 4097; i++) {
    costs[i] = distanceToTicks(i)
  }
  return costs
}

