  // }

  // return true
}

export class JumpCalculator {
  readonly engine: BaseSimulator<PlayerState>
  readonly bot: Bot
  ctx: EPhysicsCtx<PlayerState>
  readonly world: World

  constructor (sim: BaseSimulator<PlayerState>, bot: Bot, world: World, ctx: EPhysicsCtx<PlayerState>) {
    this.engine = sim
    this.bot = bot
    this.ctx = ctx
    this.world = world
  }

  public findJumpPoint (goal: Vec3, maxTicks = 20): JumpInfo | null {
    if (this.checkImmediateSprintJump(goal)) {
      return { jumpTick: 0, sprintTick: 0, backTick: Infinity }
    }

    let firstTick = 0
    let secondTick = 1

    // if less than zero, then we need to sprint before jumping.
    // we didn't cover enough distance to jump immediately.
    // if vel was up and we collided, we moved too far forward, so only sprint after jumping.
    const sprintAfterJump = this.ctx.state.vel.y > 0

    // console.log(this.ctx.state.pos, this.ctx.state.vel, goal, sprintAfterJump)
    while (firstTick < 12) {
      while (secondTick < 12 - firstTick) {
        const res = this.checkSprintJump(goal, firstTick, secondTick, sprintAfterJump)
        if (res) {
          return sprintAfterJump
            ? { jumpTick: firstTick, sprintTick: firstTick + secondTick, backTick: Infinity }
            : { jumpTick: firstTick + secondTick, sprintTick: firstTick, backTick: Infinity }
        }
        secondTick++
      }
      secondTick = 0
      firstTick++
    }

    let backTick = 1
    let sprintTick = 0
    while (backTick < 4) {
      while (sprintTick < 4 - backTick) {
        const res = this.checkSprintJump(goal, 0, sprintTick + backTick, true, backTick)
        if (res) {
          return { jumpTick: 0, sprintTick: sprintTick + backTick, backTick }
        }
        sprintTick++
      }
      sprintTick = 0
      backTick++
    }

    return null
  }

  protected resetState (): PlayerState {
    this.ctx = EPhysicsCtx.FROM_BOT(this.engine.ctx, this.bot)
    this.ctx.state.age = 0
    this.ctx.state.control = ControlStateHandler.DEFAULT()
    this.ctx.state.pos.set(this.bot.entity.position.x, this.bot.entity.position.y, this.bot.entity.position.z)
    this.ctx.state.vel.set(this.bot.entity.velocity.x, this.bot.entity.velocity.y, this.bot.entity.velocity.z)
    return this.ctx.state
  }

  protected checkImmediateSprintJump (goal: Vec3): boolean {
    const state = this.resetState()
    stateLookAt(state, goal)
    this.simJump(state)
    // console.log('immediate jump', state.pos, state.vel, goal)
    if (state.isCollidedHorizontally) return false
    if (state.onGround && state.pos.y === goal.y) return true
    return false
  }

  protected checkSprintJump (goal: Vec3, firstTicks = 0, secondTicks = 0, sprintAfterJump = false, backTicks = Infinity): boolean {
    const state = this.resetState()
    stateLookAt(state, goal)
    this.simJumpAdvanced(state, goal, {
      firstTicks,
      secondTicks,
      backTicks,
      sprintAfterJump,
      maxTicks: 20
    })
    // console.log(
    //   'sim jump',
    //   firstTicks,
    //   secondTicks,
    //   sprintAfterJump,
    //   backTicks,
    //   state.pos,
    //   state.control,
    //   state.age,
    //   goal,
    //   state.isCollidedHorizontally,
    //   state.isCollidedHorizontally,
    //   state.onGround
    // )
    if (state.isCollidedHorizontally) return false
    if (state.onGround && state.pos.y === goal.y) return true
    return false
  }

  protected simJump (state: PlayerState, maxTicks = 20): PlayerState {
    state.control.set('forward', true)
    state.control.set('jump', true)
    state.control.set('sprint', true)
    this.engine.simulateUntil(
      (state, ticks) => ticks > 0 && (state.onGround || state.isCollidedHorizontally),
      () => { },
      () => { },
      this.ctx,
      this.world,
      maxTicks
    )
    return state
  }

  protected simJumpAdvanced (
    state: PlayerState,
    goal: Vec3,
    opts: {
      firstTicks?: number
      secondTicks?: number
      backTicks?: number
      sprintAfterJump?: boolean
      maxTicks?: number
    } = {}
  ): PlayerState {
    // goddamnit ts-standard.
    const { firstTicks, secondTicks, backTicks, sprintAfterJump, maxTicks } = opts
    const ft = firstTicks ?? 0
    const st = secondTicks ?? 0
    const bt = backTicks ?? Infinity
    const sj = sprintAfterJump ?? false
    const mt = maxTicks ?? 20

    // console.log("in sim:", firstTicks, secondTicks, sprintAfterJump, maxTicks, state.control)
    this.engine.simulateUntil(
      (state, ticks) => {
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        const boundary = sj ? ft + st : ft
        // const xzVel = state.vel.offset(0, -state.vel.y, 0)
        // console.log(ticks, firstTicks, secondTicks, backTicks)
        // console.log('checking goal', state.control.get('jump'), state.control.get('forward'), state.control.get('back'), state.control.get('sprint'))
        // console.log(state.onGround, state.isCollidedHorizontally, state.isCollidedVertically, state.pos)
        // console.log(state.vel, xzVel.norm(), xzVel)
        return (state.control.get('jump') && state.onGround && ticks > boundary) || (ticks > 0 && state.isCollidedHorizontally)
      },
      () => { },
      (state, ticks) => {
        stateLookAt(state, goal)
        state.control.set('back', false)
        state.control.set('forward', false)
        state.control.set('jump', false)
        state.control.set('sprint', false)

        if (bt !== Infinity && ticks < bt) {
          state.control.set('back', true)
          state.control.set('jump', true)
        }

        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        if (ticks >= ft) {
          if (sj) state.control.set('jump', true)
          else {
            state.control.set('sprint', true)
            state.control.set('forward', true)
          }

          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          if (ticks >= ft + st) {
            // eslint-disable-next-line @typescript-eslint/strict-boolean-expressions
            if (sj) {
              state.control.set('sprint', true)
              state.control.set('forward', true)
            } else {
              state.control.set('jump', true)
            }
          }
        }
        // console.log('sim jump',firstTicks, secondTicks, sprintAfterJump, ticks, state.pos, state.control)
      },
      this.ctx,
      this.world,
      mt
    )

    return state
  }
}

export class ParkourJumpHelper {
  public readonly sim: JumpSim
  private readonly bot: Bot
  private readonly world: World

  constructor (bot: Bot, world: World) {
    this.bot = bot
    this.sim = new JumpSim(new ClimbAwarePhysics(bot.registry), world)
    this.world = world
  }

  private _buildBackupCandidates (bbs: AABB[], goalVert: Vec3, orgPos: Vec3): Vec3[] {
    const candidates = new Map<string, Vec3>()

    for (const bb of bbs) {
      for (const vert of bb.toVertices()) {
        const offsetX = Math.sign(vert.x - goalVert.x) * 0.3
        const offsetZ = Math.sign(vert.z - goalVert.z) * 0.3
        const candidate = this._snapSharedAxesToFaceCenter(vert.clone().offset(offsetX, 0, offsetZ), goalVert)
        candidates.set(`${candidate.x},${candidate.y},${candidate.z}`, candidate)
      }
    }

    return [...candidates.values()].sort((a, b) => {
      const aOrgDist = a.xzDistanceTo(orgPos)
      const bOrgDist = b.xzDistanceTo(orgPos)
      if (Math.abs(aOrgDist - bOrgDist) > 1e-6) return aOrgDist - bOrgDist

      const aGoalDist = a.distanceTo(goalVert)
      const bGoalDist = b.distanceTo(goalVert)
      if (Math.abs(aGoalDist - bGoalDist) > 1e-6) return bGoalDist - aGoalDist

      return 0
    })
  }

  public findGoalVertex (goal: AABB): Vec3 {
    // get top vertex that is closest to target.

    const pos = this.bot.entity.position

    // When `goal.minX - pos.x < pos.x - goal.maxX` the bot is past the block's
    // centre on the X axis, meaning maxX is the nearer face — NOT minX.
    // The original code had the two branches swapped (always picked the far
    // corner), causing the bot to aim at the wrong vertex and fail the
    // yaw-alignment check before every diagonal parkour jump.
    const closerX = goal.minX - pos.x < pos.x - goal.maxX ? goal.maxX : goal.minX
    const closerZ = goal.minZ - pos.z < pos.z - goal.maxZ ? goal.maxZ : goal.minZ

    // 3 closest vectors to source position
    const verts = [
      v(closerX, goal.maxY, closerZ),
      v(closerX, goal.maxY, goal.minZ),
      v(closerX, goal.maxY, goal.maxZ),
      v(goal.minX, goal.maxY, closerZ),
      v(goal.maxX, goal.maxY, closerZ)
    ]

    // if position of bot and position of goal are less than 1 block on any axis away, push a vector that is a straight line to it.
    // for example: bot pos is 0.7,0,0 and goal is 0,0,0 to 1,0,1, then push 0.7,0,0

    if (goal.minX - pos.x < 1 && pos.x - goal.maxX < 1) {
      verts.push(v(goal.maxX - pos.x + goal.minX, goal.maxY, goal.minZ))
      verts.push(v(goal.maxX - pos.x + goal.minX, goal.maxY, goal.maxZ))
    }

    if (goal.minZ - pos.z < 1 && pos.z - goal.maxZ < 1) {
      verts.push(v(goal.minX, goal.maxY, goal.maxZ - pos.z + goal.minZ))
      verts.push(v(goal.maxX, goal.maxY, goal.maxZ - pos.z + goal.minZ))
    }

    let minDist = Infinity
    let minVert = verts[0]
    for (const vert of verts) {
      const dist = vert.distanceTo(pos)
      if (dist < minDist) {
        minDist = dist
        minVert = vert
      }
    }

    return minVert
  }

  public findBackupVertex (bbs: AABB[], goalVert: Vec3, orgPos: Vec3 = this.bot.entity.position): Vec3 {
    const candidates = this._buildBackupCandidates(bbs, goalVert, orgPos)
    return candidates[0] ?? orgPos.clone()
  }

  public findViableBackupVertex (goal: Vec3, eyeTarget?: Vec3, orgPos: Vec3 = this.bot.entity.position): Vec3 | null {
    const bbs = getUnderlyingBBs(this.world, orgPos, 0.6)
    const goalVert = eyeTarget ?? this.findGoalVertex(AABB.fromBlockPos(goal))

    for (const candidate of this._buildBackupCandidates(bbs, goalVert, orgPos)) {
      if (this.simBackupJump(goal, goalVert, candidate, orgPos)) {
        return candidate
      }
    }

    return null
  }

  private _snapSharedAxesToFaceCenter (backupVert: Vec3, goalVert: Vec3): Vec3 {
    const result = backupVert.clone()

    if (Math.abs(result.x - goalVert.x) <= 1e-6) {
      result.x = Math.floor(goalVert.x) + 0.5
    }

    if (Math.abs(result.z - goalVert.z) <= 1e-6) {
      result.z = Math.floor(goalVert.z) + 0.5
    }

    return result
  }

  public simJumpFromEdge (srcBBs: AABB[], goal: Vec3, eyeTarget?: Vec3): boolean {
    // const bbs = this.getUnderlyingBBs(this.bot.entity.position, 0.6);
    // console.log(bbs)

    const goalVert = eyeTarget ?? this.findGoalVertex(AABB.fromBlockPos(goal))

    const goalBBs = this.world.getBlockInfo(goal).getBBs()

    const ctx = EPhysicsCtx.FROM_BOT(this.sim.ctx, this.bot)

    const state = this.sim.simulateJumpFromEdgeOfBlock(ctx, srcBBs, goalVert, goalBBs, true, 40)

    // console.log('sim jump from edge', state.age, state.pos, goalVert, state.onGround, state.isCollidedHorizontally, state.control, state.isInWater)
    const reached = JumpSim.getReachedAABB(goalBBs)
    return reached(state, 0) as boolean
  }

  public simFallOffEdge (goal: Vec3, target?: Vec3): boolean {
    const goalVert = this.findGoalVertex(AABB.fromBlockPos(goal))

    // console.log('sim jump goals', goal, goalVert)
    const ctx = EPhysicsCtx.FROM_BOT(this.sim.ctx, this.bot)

    const goalBBs = this.world.getBlockInfo(goal).getBBs()

    ctx.state.control = ControlStateHandler.DEFAULT()
    if (target != null) stateLookAt(ctx.state, target)
    ctx.state.control.set('forward', true)
    ctx.state.control.set('jump', false)
    ctx.state.control.set('sprint', true)

    const orgPos = this.bot.entity.position.clone()

    const reached0 = JumpSim.getReachedAABB(goalBBs)
    const reached: SimulationGoal = (state, ticks) => state.onGround && reached0(state, ticks)
    // console.log('fall off edge init', orgPos)
    const state = this.sim.simulateUntil(
      reached,
      () => { },
      (state) => {
        if (state.pos.y === orgPos.y) {
          // console.log('fall off edge check', state.age, state.pos)
        }
        stateLookAt(state, goalVert)
      },
      ctx,
      this.world,
      45
    )

    // console.log(reached(state, 0), reached0(state, 0), reached0(state, 1), state.age, orgPos, state.pos, goal, state.onGround, state.isCollidedHorizontally, state.control);
    return reached0(state, 0) as boolean
  }

  public simForwardMove (goal: Vec3, eyeTarget?: Vec3, jump = true, ...constraints: SimulationGoal[]): boolean {
    // console.log('sim jump goals', goal, goalVert)
    const ctx = EPhysicsCtx.FROM_BOT(this.sim.ctx, this.bot)
    // const goalCenter = goal.floored().offset(0.5, 0, 0.5)

    const goalBBs = this.world.getBlockInfo(goal).getBBs()

    const target = eyeTarget ?? goal

    // const orgPos = this.bot.entity.position.clone()

    const g = JumpSim.getReachedAABB(goalBBs)
    let reached: SimulationGoal = (state, ticks) => {
      // if (state.pos.y >= orgPos.y)
      // console.log('sim check', state.age, state.pos)
      return g(state, ticks)
    }

    if (constraints.length > 0) {
      const old = reached
      reached = (state, ticks) => {
        for (const constraint of constraints) {
          if (!(constraint(state, ticks) as boolean)) return false
        }
        return old(state, ticks)
      }
    }

    const state = this.sim.simulateUntil(
      reached,
      JumpSim.getCleanupPosition(target),
      JumpSim.buildFullController(
        JumpSim.getControllerStraightAim(target),
        JumpSim.getControllerStrafeAim(target, true),
        JumpSim.getControllerSmartMovement(target, true),
        (state, ticks) => {
          state.control.sneak = false
          state.control.set('jump', jump && ticks === 0)
        }
      ),
      ctx,
      this.world,
      45
    )

    const testwtf = reached(state, 0) as boolean
    return testwtf
  }

  public simBackupJump (goal: Vec3, eyeTarget?: Vec3, backupTarget?: Vec3, orgPos: Vec3 = this.bot.entity.position): boolean {
    const bbs = getUnderlyingBBs(this.world, orgPos, 0.6)

    const goalBBs = this.world.getBlockInfo(goal).getBBs()
    const goalVert = eyeTarget ?? this.findGoalVertex(AABB.fromBlockPos(goal))
    const lazyFix = backupTarget ?? this.findBackupVertex(bbs, goalVert)

    const reached = JumpSim.getReachedAABB(goalBBs)

    const ctx = EPhysicsCtx.FROM_BOT(this.sim.ctx, this.bot)

    this.sim.simulateBackUpBeforeJump(ctx, lazyFix, true, true, 40)
    const state = this.sim.simulateJumpFromEdgeOfBlock(ctx, bbs, goalVert, goalBBs, true, 40)
    return reached(state, 0) as boolean
  }
}

import { Vec3 } from 'vec3'
import { Move } from '../move'
import type { Goal } from '../goals'
import { Movement } from './movement'
import { MovementProvider } from './movementProvider'
import { MovementExecutor } from './movementExecutor'
import { CancelError } from '../exceptions'
import { COST_INF, JUMP_ONE_BLOCK_COST } from './costs'
import { posToYawPitchFromEye } from '../../utils'

const { PlayerState } = require('prismarine-physics')
const log = require('debug')('minecraft-pathfinding:neo')
type Steering = { yaw: number; forward: boolean; back: boolean; left: boolean; right: boolean }
type FlightStep = Steering & { jump: boolean; sneak: boolean; position: Vec3 }
type Flight = { state: any; steps: FlightStep[]; score: number; jumped: boolean }

function angularDifference (a: number, b: number): number {
  return Math.atan2(Math.sin(a - b), Math.cos(a - b))
}

// Rotate the input axes along with the camera, preserving the exact world-space
// acceleration. Braking uses back/strafe instead of turning away from the landing.
function steering (headingYaw: number, lookYaw: number, jumping = false): Steering {
  const quarter = jumping ? 0 : Math.round(angularDifference(lookYaw, headingYaw) / (Math.PI / 2))
  const axis = (quarter + 4) % 4
  return { yaw: headingYaw + quarter * Math.PI / 2, forward: axis === 0, right: axis === 1, back: axis === 2, left: axis === 3 }
}

/** Geometry from Rewrite's examples/neos, with both escape sides checked independently. */
export class NeoProvider extends MovementProvider {
  movementDirs = Movement.cardinalDirs

  provideMovements(node: Move, storage: Move[], _goal: Goal, closed: Set<string>): void {
    if (!this.getBlockInfo(node, 0, -1, 0).solidFull) return
    if (![0, 1, 2].every((y) => this.getBlockInfo(node, 0, y, 0).walkthrough)) return
    for (const dir of this.movementDirs) {
      for (let distance = 2; distance <= (this.settings.allowSprinting ? 3 : 2); distance++) {
        const feet = this.getBlockInfo(node, dir.x * distance, 0, dir.z * distance)
        if (closed.has(`${feet.position.x},${feet.position.y},${feet.position.z}`)) continue
        if (
          !this.getBlockInfo(feet.position, 0, -1, 0).solidFull ||
          ![0, 1, 2].every((y) => this.getBlockInfo(feet.position, 0, y, 0).walkthrough)
        )
          continue
        if (
          !Array.from({ length: distance - 1 }, (_, i) => i + 1).every(
            (step) =>
              this.getBlockInfo(node, dir.x * step, 0, dir.z * step).solidFull &&
              this.getBlockInfo(node, dir.x * step, 1, dir.z * step).solidFull
          )
        )
          continue
        const sides = [-1, 1].filter((sign) => {
          const side = new Vec3(-dir.z * sign, 0, dir.x * sign)
          for (let step = 0; step <= distance; step++) {
            for (let y = 0; y <= 2; y++) {
              if (
                !this.getBlockInfo(node, dir.x * step + side.x, y, dir.z * step + side.z)
                  .walkthrough
              )
                return false
            }
          }
          return true
        })
        if (sides.length === 0) continue
        const cost =
          JUMP_ONE_BLOCK_COST +
          this.travelCost(distance) +
          this.settings.jumpCost +
          this.exclusionStep(feet)
        if (cost >= COST_INF) continue
        const move = Move.fromPrevious(cost, feet.position.offset(0.5, 0, 0.5), node, this)
        move.metadata = { neoSides: sides, neoDir: dir, neoOrigin: node.cachedVec }
        storage.push(move)
      }
    }
  }
}

/** Plan a short flight with the same prismarine-physics engine that moves Mineflayer. */
export class NeoExecutor extends MovementExecutor {
  private flight: FlightStep[] = []
  private step = 0
  private flightListener?: () => void
  private complete = false
  private failure?: Error

  override reset(): void {
    if (this.flightListener != null) this.bot.off('physicsTick', this.flightListener)
    this.flightListener = undefined
    this.complete = false
    this.failure = undefined
    this.flight = []
    this.step = 0
    super.reset()
  }

  override isAlreadyCompleted(move: Move): boolean {
    return this.landed(move)
  }

  private landed(move: Move): boolean {
    const pos = this.bot.entity.position
    return (
      this.bot.entity.onGround &&
      Math.abs(pos.y - move.exitPos.y) < 0.05 &&
      pos.floored().equals(move.exitPos.floored())
    )
  }

  private direction(move: Move): Vec3 {
    if (move.metadata?.neoDir != null) return move.metadata.neoDir
    const dir = move.exitPos.minus(move.entryPos)
    dir.y = 0
    return dir.normalize()
  }

  override align(move: Move): boolean {
    const dir = this.direction(move)
    const sign = move.metadata?.neoSides[0] ?? 1
    const side = new Vec3(-dir.z * sign, 0, dir.x * sign)
    const origin: Vec3 = move.metadata?.neoOrigin ?? move.entryPos.floored()
    const target = origin.offset(0.5, 0, 0.5).plus(side.scaled(0.73)).minus(dir.scaled(0.2))
    const delta = target.minus(this.bot.entity.position)
    const velocity = this.bot.entity.velocity
    this.bot.clearControlStates()
    this.bot.setControlState('sneak', true)
    if (
      Math.hypot(delta.x, delta.z) < 0.045 &&
      Math.hypot(velocity.x, velocity.z) < 0.005 &&
      this.bot.entity.onGround
    )
      return true
    // Counter momentum instead of waiting for velocity to decay to almost zero.
    const aim = delta.minus(new Vec3(velocity.x, 0, velocity.z).scaled(2))
    const view = posToYawPitchFromEye(this.bot.entity.position, 1.62, move.exitPos.offset(0, 0.15, 0))
    const input = steering(Math.atan2(-aim.x, -aim.z), view.yaw)
    this.bot.entity.yaw = input.yaw
    this.bot.entity.pitch = view.pitch
    for (const control of ['forward', 'back', 'left', 'right'] as const) this.bot.setControlState(control, input[control] && Math.hypot(aim.x, aim.z) > 0.015)
    if (this.bot.entity.position.y < move.entryPos.y - 0.2)
      throw new CancelError('Neo: takeoff support was lost')
    return false
  }

  async performInit(move: Move): Promise<void> {
    this.bot.clearControlStates()
    this.bot.setControlState('sneak', true)
    this.flight = await this.planFlight(move)
    if (this.aborted || this.bot.pathfinder.abortCalculation) return
    if (this.flight.length === 0)
      throw new CancelError('Neo: no collision-free flight to the landing block')
    this.step = 0
    this.applyStep(this.flight[this.step++], move)
    // Mineflayer can emit several catch-up ticks in one event-loop turn.
    // Flight controls must advance synchronously on every one of them.
    const flightListener = (): void => {
      if (
        this.flightListener !== flightListener ||
        this.aborted ||
        this.bot.pathfinder.abortCalculation
      )
        return
      try {
        this.advanceFlight(move)
      } catch (error) {
        this.failure = error as Error
        log('flight failed: %s at %O', this.failure.message, this.bot.entity.position)
      }
      if (this.complete || this.failure != null) {
        this.bot.off('physicsTick', flightListener)
        this.flightListener = undefined
        this.bot.clearControlStates()
      }
    }
    this.flightListener = flightListener
    this.bot.on('physicsTick', flightListener)
  }

  private applyStep(step: FlightStep, move: Move): void {
    this.bot.clearControlStates()
    this.bot.entity.yaw = step.yaw
    this.bot.entity.pitch = posToYawPitchFromEye(this.bot.entity.position, 1.62, move.exitPos.offset(0, 0.15, 0)).pitch
    this.bot.setControlState('sprint', this.settings.allowSprinting)
    for (const control of ['forward', 'back', 'left', 'right'] as const) this.bot.setControlState(control, step[control])
    this.bot.setControlState('jump', step.jump)
    this.bot.setControlState('sneak', step.sneak)
  }

  performPerTick(move: Move): boolean {
    if (this.failure != null) throw this.failure
    return this.complete
  }

  private advanceFlight(move: Move): void {
    if (this.landed(move)) {
      this.complete = true
      return
    }
    if (this.bot.entity.position.y < move.exitPos.y - 0.2)
      throw new CancelError('Neo: landing was missed')
    const previous = this.flight[this.step - 1]
    if (previous != null && previous.position.distanceTo(this.bot.entity.position) > 0.4) {
      throw new CancelError('Neo: server position differs from the predicted flight')
    }
    const next = this.flight[this.step++]
    if (next == null) throw new CancelError('Neo: flight ended without landing')
    this.applyStep(next, move)
  }

  private async planFlight(move: Move): Promise<FlightStep[]> {
    const dir = this.direction(move)
    const sign = move.metadata?.neoSides[0] ?? 1
    const side = new Vec3(-dir.z * sign, 0, dir.x * sign)
    const source: Vec3 = move.metadata?.neoOrigin ?? move.entryPos.floored()
    const origin = source.offset(0.5, 0, 0.5)
    const distance = move.exitPos.xzDistanceTo(origin)
    const physicsWorld = { getBlock: (position: Vec3) => this.world.getBlock(position) }
    const controls = {
      forward: true,
      back: false,
      left: false,
      right: false,
      sneak: false,
      sprint: this.settings.allowSprinting,
      jump: true
    }
    const initial = new PlayerState(this.bot, controls)
    log(
      'planning from %O velocity=%O onGround=%s jumpTicks=%s',
      initial.pos,
      initial.vel,
      initial.onGround,
      initial.jumpTicks
    )
    let beam: Flight[] = [{ state: initial, steps: [], score: 0, jumped: false }]
    // Bounded beam; only run it for an actual Neo, never for every A* neighbor.
    const deadline = performance.now() + 750
    for (let tick = 0; tick < 22 && beam.length > 0; tick++) {
      if (this.aborted || this.bot.pathfinder.abortCalculation || performance.now() > deadline)
        return []
      const candidates: Flight[] = []
      for (const flight of beam) {
        const progress = flight.state.pos.minus(origin).dot(dir)
        const angles =
          progress < distance - 0.2
            ? [110, 75, 45, 20, 0, -20, -45, -75, -110]
            : [-150, -110, -75, -45, 0, 75, 150]
        for (const angle of angles) {
          const launches =
            !flight.jumped && flight.state.onGround && tick < 4 ? [true, false] : [false]
          for (const jump of launches) {
            const rad = (angle * Math.PI) / 180
            const heading = dir.scaled(Math.cos(rad)).plus(side.scaled(Math.sin(rad)))
            const look = move.exitPos.minus(flight.state.pos)
            const lookYaw = Math.atan2(-look.x, -look.z)
            const input = steering(Math.atan2(-heading.x, -heading.z), lookYaw, jump)
            if (jump && Math.abs(angularDifference(input.yaw, lookYaw)) > Math.PI / 3) continue
            const turn = Math.abs(angularDifference(input.yaw, flight.state.yaw))
            if (flight.jumped && turn > Math.PI / 3) continue
            const { yaw, ...buttons } = input
            const state = Object.assign(
              Object.create(Object.getPrototypeOf(initial)),
              flight.state,
              {
                pos: flight.state.pos.clone(),
                vel: flight.state.vel.clone(),
                yaw,
                control: { ...controls, ...buttons, jump, sneak: flight.jumped && flight.state.onGround }
              }
            )
            ;(this.bot.physics as any).simulatePlayer(state, physicsWorld)
            if (
              state.isCollidedHorizontally ||
              state.isInWater ||
              state.isInLava ||
              state.pos.y < move.exitPos.y - 0.05
            )
              continue
            const jumped = flight.jumped || jump
            if (!jumped && !state.onGround) continue
            const steps = [
              ...flight.steps,
              { ...input, jump, sneak: state.control.sneak, position: state.pos.clone() }
            ]
            const offset = state.pos.minus(origin)
            const along = offset.dot(dir)
            const across = offset.dot(side)
            if (jumped && tick > 2 && state.onGround) {
              if (
                state.pos.floored().equals(move.exitPos.floored()) &&
                state.pos.xzDistanceTo(move.exitPos) < 0.65
              )
                return steps
              if (along < distance - 0.3) continue
            }
            // Stay outside the wall until the full player box has cleared its back face.
            const desiredAcross = along < distance - 0.2 ? 0.85 : 0
            const future = state.pos.plus(state.vel.scaled(3))
            const score =
              future.xzDistanceTo(move.exitPos) +
              Math.abs(across - desiredAcross) * 0.3 +
              Math.max(0, -along) * 2 + turn * 0.02
            candidates.push({ state, steps, score, jumped })
          }
        }
      }
      candidates.sort((a, b) => a.score - b.score)
      const seen = new Set<string>()
      beam = []
      let launchesKept = 0
      let flightsKept = 0
      for (const candidate of candidates) {
        if (candidate.jumped ? flightsKept >= 48 : launchesKept >= 16) continue
        const { pos, vel } = candidate.state
        const key =
          `${candidate.jumped}:` +
          [pos.x, pos.z, vel.x * 2, vel.z * 2].map((n) => Math.round(n * 12)).join(',')
        if (seen.has(key)) continue
        seen.add(key)
        beam.push(candidate)
        if (candidate.jumped) flightsKept++
        else launchesKept++
        if (beam.length === 64) break
      }
      // Keep packets, stop commands and physics responsive during flight planning.
      await new Promise<void>((resolve) => setImmediate(resolve))
    }
    return []
  }
}

