    for (let i = 0; i <= scenario.edge; i++) world.setBlock(position(i), i > scenario.edge - scenario.rim ? scenario.block : 'stone')
    for (let i = scenario.edge + 6; i <= scenario.edge + 9; i++) world.setBlock(position(i), 'stone')
