    assert.equal(finished, 0)
    await navigator.stop()
    await running
    assert.equal(rig.bot.getControlState('forward'), false)
    assert.equal(rig.bot.listenerCount('entityMoved'), 0)
  } finally {
    await cleanup(rig)
  }
})

