function ocean (version: string) {
  const world = createFlatWorld(version, 56, { renderDistance: 1 })
  for (let x = -3; x <= 12; x++) for (let z = -3; z <= 3; z++) {
    for (let y = 56; y <= 63; y++) world.setBlock(new Vec3(x, y, z), 'water')
  }
