})

for (const surface of ['stone', 'lava', 'shallow water', 'covered water']) {
  test(`high drops reject ${surface} even when unlimited water drops are enabled`, async () => {
    const world = createFlatWorld('1.20.4', -64, { renderDistance: 1 })
