          options,
        );
        target.position.x = 12.5;
        controller.select(target);
        bot.emit("physicsTick");
        await flush();
        const before = packets.length;
        time += 50;
        bot.emit("physicsTick");
        await flush();
        assert.ok(
          packets
            .slice(before)
            .some((packet) => packet.name === (version === "1.8.8" ? "block_place" : "use_item")),
